# ── Window-function helpers (module-level for reuse) ─────────────────────────

def _min_skip_nan(ok):
    """MIN over valid values: NaN is skipped unless every value is NaN (DuckDB, F-070)."""
    real = ok[~np.isnan(ok)]
    return real.min() if real.size else np.nan


def _cum_sum_skip_null(arr, valid):
    """Running sum over valid values: NULL until the first valid one, then carried on (NaN
    propagates). Returns (values, null mask)."""
    return np.cumsum(np.where(valid, arr, 0.0)), np.cumsum(valid) == 0


def _order_codes(a, descending: bool = False) -> np.ndarray:
    """int64 sort code per row, equal for rows that tie in a window ORDER BY like DuckDB: NaN is the
    largest value (so first under DESC), -0.0 ties with 0.0, NULL is last in both directions and
    NULLs tie with each other (F-084)."""
    a = _combine(a)
    if pa.types.is_dictionary(a.type):
        a = a.dictionary_decode()
    valid = _np_of(pc.is_valid(a))
    codes = np.zeros(len(a), dtype=np.int64)
    if a.type in (pa.float32(), pa.float64()):
        x = _np_of(pc.fill_null(_canonical_floats(a), _npscalar(0, type=a.type)))
        uniq, inv = np.unique(x[valid], return_inverse=True)     # NaN sorts last and merges
        k = len(uniq)
        codes[valid] = inv.reshape(-1)
    else:
        dense = _np_of(pc.rank(a, sort_keys="ascending", null_placement="at_end", tiebreaker="dense"))
        k = int(dense[valid].max()) if valid.any() else 0
        codes[valid] = dense[valid].astype(np.int64) - 1
    if descending:
        codes[valid] = k - 1 - codes[valid]
    codes[~valid] = k
    return codes


def _shift_rows(src, rows, args, lead):
    """lag / lead: for the rows of one ordered partition, record the row each one reads (-1: none)."""
    k = int(args[1]) if len(args) > 1 and args[1] is not None else 1
    m = len(rows)
    if k < 0:
        k, lead = -k, not lead
    if k >= m:
        return
    if lead:
        src[rows[:m - k]] = rows[k:]
    else:
        src[rows[k:]] = rows[:m - k]


def _cast_default(value, typ):
    """A lag / lead default cast to the column's type like DuckDB: a float into an integer column
    rounds half away from zero, text parses, a number into a string column is its text; a value
    that does not fit raises."""
    if pa.types.is_string(typ) or pa.types.is_large_string(typ):
        return pa.scalar(str(value), type=typ)
    if pa.types.is_integer(typ):
        if isinstance(value, str):
            value = int(value)
        elif isinstance(value, float):
            value = int(np.sign(value) * np.floor(abs(value) + 0.5))
    return pa.scalar(value, type=typ)


def _take_shifted(arr, src, args):
    """The input array gathered at *src* (-1 gives NULL, or the default); dtype and NULLs kept."""
    none = src < 0
    out = pc.take(arr, pa.array(np.where(none, 0, src), mask=none) if len(arr) else pa.nulls(len(src), pa.int64()))
    default = args[2] if len(args) > 2 else None
    if default is not None:           # only rows that read nothing get it; a source NULL stays NULL
        out = pc.if_else(pa.array(none), _cast_default(default, out.type), out)
    return out


def _window_rank(a, descending: bool = False) -> np.ndarray:
    """Standard competition ranking: ties share rank, gaps follow (1,2,2,4...)."""
    codes = _order_codes(a, descending)
    return (np.searchsorted(np.sort(codes), codes, side="left") + 1).astype(np.float64)


def _window_dense_rank(a, descending: bool = False) -> np.ndarray:
    """Dense ranking: ties share rank with no gaps (1,2,2,3...)."""
    _, inv = np.unique(_order_codes(a, descending), return_inverse=True)
    return (inv.reshape(-1) + 1).astype(np.float64)


class CustomOpsCompiler(GraphCompiler):
    """Compiles a LogicalPlan into a MAX Graph with custom Mojo kernels.

    Extends GraphCompiler with:
    1. Pre-filter   -- inherited _strip_filters applies Filter nodes in PyArrow.
    2. Group ids    -- PyArrow dictionary-encodes group-by keys into int32 ids.
    3. Kernel dispatch -- grouped sum/min/max/mean/count routed to Mojo kernels.
    4. Keys in result -- group-by key columns are prepended to the output table.
    5. GPU path     -- kernels run on GPU when device='gpu' or device='auto' (N > 100K).
    6. Graph caching -- compiled models are cached by plan signature + input schema.
    7. Post-ops     -- Sort/Limit/Distinct applied via Mojo kernels after graph execution.
    """

    def __init__(self, kernels_path: str = None, device: str = "cpu"):
        super().__init__(device=device)
        self.kernels_path = kernels_path or KERNELS_PATH
        self.last_compile_provenance = {}
        self._aot = _load_aot_kernels()
        self._aot_gpu_obj = None      # GPU AOT library: fetched on first GPU use, never for cpu
        if self._device_arg == "auto":
            # Speculative: initialise the GPU in the background so a query that turns out
            # to need it finds it ready, and one that does not never waits for it.
            _start_gpu_warmup()

    def _create_session(self):
        return _get_or_create_session(self._session_device, self._driver_device)

    @property
    def _aot_gpu(self):
        """GPU AOT kernels, or None when this compiler is not on the GPU (or it has none).

        Created lazily and shared process-wide; waits for the warm-up if that is running
        rather than initialising a second time."""
        if self._session_device != "gpu" or not GPU_AOT_AVAILABLE:
            return None
        if self._aot_gpu_obj is None:
            warm = _process_gpu_warmup()           # starts it if nobody has; reused, never initialised twice
            self._aot_gpu_obj = warm.result if warm.wait() else None
        return self._aot_gpu_obj

    @_aot_gpu.setter
    def _aot_gpu(self, value):
        self._aot_gpu_obj = value

    def _resolve_auto(self, plan) -> None:
        """device='auto': decide CPU vs GPU for this query before any operator runs.

        Same rule as before (GPU when one is usable and the data exceeds
        AUTO_GPU_THRESHOLD rows), but the GPU is only awaited when the query is big enough
        to want it, so small queries never wait for -- or pay for -- GPU start-up."""
        if not self._auto_pending:
            return
        self._auto_pending = False
        if _scan_rows(plan) <= AUTO_GPU_THRESHOLD or not GPU_AOT_AVAILABLE:
            return
        warm = _process_gpu_warmup()
        if not warm.wait():
            return
        acc = _max_accelerator()
        if acc is None:
            return
        self._gpu_driver = acc
        self._has_gpu = True
        self._switch_to_gpu()

    def _switch_to_gpu(self) -> None:
        self._driver_device = self._gpu_driver
        self._device_ref = DeviceRef.GPU(0)
        self._session_device = "gpu"
        self.session = None      # graph fallbacks build a session for the new device on demand

    def _maybe_switch_device(self, N: int) -> None:
        """For device='auto': re-evaluate CPU vs GPU based on row count.

        Threshold: N > AUTO_GPU_THRESHOLD and GPU available -> GPU, otherwise CPU.
        """
        if self._device_arg != "auto":
            return
        want_gpu = self._has_gpu and N > AUTO_GPU_THRESHOLD
        have_gpu = (self._session_device == "gpu")
        if want_gpu == have_gpu:
            return
        if want_gpu:
            self._switch_to_gpu()
        else:
            self._driver_device = None      # CPU handles are made on first use
            self._device_ref = None
            self._session_device = "cpu"
            self.session = None

    @staticmethod
    def _normalize_numeric_dtype(arr: np.ndarray) -> Union[np.ndarray, None]:
        """Normalize numeric arrays to MAX-friendly dtypes."""
        kind = arr.dtype.kind
        if kind in ("i", "u"):
            if arr.dtype not in (np.dtype("int32"), np.dtype("int64")):
                return arr.astype(np.int64, copy=False)
            return arr
        if kind == "f":
            if arr.dtype not in (np.dtype("float32"), np.dtype("float64")):
                return arr.astype(np.float64, copy=False)
            return arr
        if kind == "b":
            return arr.astype(np.bool_, copy=False)
        return None

    @staticmethod
    def _arrow_array_to_numpy_view(arr: pa.Array) -> Union[np.ndarray, None]:
        """Try zero-copy NumPy view from Arrow primitive array buffers."""
        if arr.null_count != 0:
            return None
        typ = arr.type
        if pa.types.is_int32(typ):
            dtype = np.int32
            itemsize = 4
        elif pa.types.is_int64(typ):
            dtype = np.int64
            itemsize = 8
        elif pa.types.is_uint32(typ):
            dtype = np.uint32
            itemsize = 4
        elif pa.types.is_uint64(typ):
            dtype = np.uint64
            itemsize = 8
        elif pa.types.is_float32(typ):
            dtype = np.float32
            itemsize = 4
        elif pa.types.is_float64(typ):
            dtype = np.float64
            itemsize = 8
        else:
            return None

        buffers = arr.buffers()
        if len(buffers) < 2 or buffers[1] is None:
            return None

        offset_bytes = arr.offset * itemsize
        try:
            return np.frombuffer(buffers[1], dtype=dtype, count=len(arr), offset=offset_bytes)
        except Exception:
            return None

    @staticmethod
    def _is_numeric_arrow_type(typ) -> bool:
        """Return True for Arrow types we can convert to numpy tensors."""
        return (pa.types.is_integer(typ) or pa.types.is_floating(typ)
                or pa.types.is_boolean(typ))

    def _column_to_numpy_cached(self, col: Union[pa.Array, pa.ChunkedArray]) -> tuple[Union[np.ndarray, None], bool, bool]:
        """Convert Arrow column to numeric NumPy with zero-copy-first strategy."""
        if isinstance(col, pa.ChunkedArray):
            if len(col.chunks) == 1:
                arr = col.chunks[0]
            else:
                arr = _combine(col)
        else:
            arr = col

        view = self._arrow_array_to_numpy_view(arr)
        if view is not None:
            norm = self._normalize_numeric_dtype(view)
            if norm is not None:
                out = norm if norm.flags['C_CONTIGUOUS'] else np.ascontiguousarray(norm)
                return out, False, True

        try:
            np_arr = _np_of(arr, zero_copy_only=True)
            norm = self._normalize_numeric_dtype(np_arr)
            if norm is not None:
                out = norm if norm.flags['C_CONTIGUOUS'] else np.ascontiguousarray(norm)
                return out, False, False
        except Exception:
            pass

        try:
            np_arr = _np_of(arr, zero_copy_only=False)
            norm = self._normalize_numeric_dtype(np_arr)
            if norm is not None:
                out = norm if norm.flags['C_CONTIGUOUS'] else np.ascontiguousarray(norm)
                return out, True, False
        except Exception:
            return None, False, False
        return None, False, False

    def _to_gpu_input(self, arr: np.ndarray) -> tuple[Any, str]:
        """Build GPU input buffer using fastest available safe path."""
        try:
            return driver.Buffer.from_numpy(arr).to(self._gpu_driver), "from_numpy"
        except Exception:
            contiguous = np.ascontiguousarray(arr)
            return driver.Buffer.from_numpy(contiguous).to(self._gpu_driver), "from_numpy_contiguous"

    @classmethod
    def _can_compile_predicate_gpu(cls, expr: Expr) -> bool:
        """Return True if this predicate can be compiled to a MAX Graph int32 mask node.

        Supports numeric col references, numeric literals, and gt/ge/lt/le/eq/and/or
        combinations. String columns, nulls, and non-comparison ops are not supported.
        """
        op = expr.op
        if op == "col":
            return True
        if op == "lit":
            return isinstance(expr.args[0], (int, float, bool))
        if op in ("gt", "ge", "lt", "le", "eq", "ne", "and", "or"):
            return all(cls._can_compile_predicate_gpu(a) for a in expr.args)
        # isin, startswith, case_when, not -> need PyArrow eval -> CPU path only
        return False

    def _visit_predicate_to_mask(self, expr: Expr, nodes) -> Any:
        """Compile a filter predicate Expr into an int32 mask graph node (0=skip, 1=keep).

        Called inside a MAX Graph context. The returned node has dtype int32 and
        the same shape as the input column tensors.
        """
        op = expr.op
        if op in ("gt", "ge", "lt", "le", "eq"):
            lhs = self._visit_expr(expr.args[0], nodes)
            rhs = self._visit_expr(expr.args[1], nodes)
            return ops.cast(_CMP_OPS[op](lhs, rhs), DType.int32)
        if op == "ne":
            lhs = self._visit_expr(expr.args[0], nodes)
            rhs = self._visit_expr(expr.args[1], nodes)
            eq_node = ops.cast(ops.equal(lhs, rhs), DType.int32)
            one = ops.constant(np.array([1], dtype=np.int32), dtype=DType.int32, device=self._device_ref)
            return ops.sub(one, eq_node)
        if op == "and":
            l = self._visit_predicate_to_mask(expr.args[0], nodes)
            r = self._visit_predicate_to_mask(expr.args[1], nodes)
            return ops.mul(l, r)
        if op == "or":
            l = self._visit_predicate_to_mask(expr.args[0], nodes)
            r = self._visit_predicate_to_mask(expr.args[1], nodes)
            zero = ops.constant(0, dtype=DType.int32, device=self._device_ref)
            return ops.cast(ops.greater(ops.add(l, r), zero), DType.int32)
        if op == "col":
            return ops.cast(nodes[expr.args[0]], DType.int32)
        if op == "lit":
            val = expr.args[0]
            if isinstance(val, int):
                return ops.constant(val, dtype=DType.int64, device=self._device_ref)
            return ops.constant(float(val), dtype=DType.float32, device=self._device_ref)
        raise ValueError(f"Cannot compile predicate op '{op}' to GPU mask.")


    # -- Derived-column pre-computation (case_when / isin / startswith) ----

    @staticmethod
    def _needs_precompute(expr) -> bool:
        """True if expr contains case_when, isin, startswith, or window ops anywhere."""
        if expr.op in ("case_when", "isin", "startswith", "contains", "like", "str_slice", "not", "year", "is_null",
                       "year_days", "rank", "dense_rank", "row_number", "lag", "lead", "cum_sum",
                       "window", "coalesce", "abs", "cast", "f32", "add_us", *_ARROW_ONLY_OPS):
            return True
        from .lazy_expr import Expr as _Expr
        return any(isinstance(a, _Expr) and CustomOpsCompiler._needs_precompute(a)
                   for a in expr.args)

    def _arith_operands(self, args, table):
        """Operands of + - * /; a numeric literal next to an array takes the array's kind instead of
        becoming a float32 array: an integer literal keeps an integer column integer (and exact
        above 2**24), a float literal next to a float64 column is not rounded to float32."""
        def literal(e):
            return e.args[0] if e.op == "lit" and _is_number(e.args[0]) else None
        l_lit, r_lit = literal(args[0]), literal(args[1])
        if (l_lit is None) == (r_lit is None):
            return self._eval_expr_arrow(args[0], table), self._eval_expr_arrow(args[1], table)
        value, other = (l_lit, args[1]) if l_lit is not None else (r_lit, args[0])
        arr = self._eval_expr_arrow(other, table)
        typ = arr.type
        if pa.types.is_floating(typ):
            if isinstance(value, np.float64) and typ == pa.float32():     # a DOUBLE literal (F-106): the float32 array widens
                arr = pc.cast(arr, pa.float64())
                typ = arr.type
            scalar = _npscalar(float(value), type=typ)
        elif pa.types.is_integer(typ):
            scalar = _npscalar(value) if isinstance(value, int) else _npscalar(float(value), type=pa.float64())
        else:
            return (self._eval_expr_arrow(args[0], table), self._eval_expr_arrow(args[1], table))
        return (scalar, arr) if l_lit is not None else (arr, scalar)

    def _cmp_operands(self, args, table):
        """Operands of a comparison; a numeric literal next to a float32 column stays a scalar
        of the column's precision (see ``_align_literals``) instead of a float array."""
        def literal(e):
            return e.args[0] if e.op == "lit" and _is_number(e.args[0]) else None
        l_lit, r_lit = literal(args[0]), literal(args[1])
        if l_lit is not None and r_lit is None:
            rhs = self._eval_expr_arrow(args[1], table)
            if isinstance(l_lit, int) and pa.types.is_integer(rhs.type):
                return _npscalar(l_lit), rhs            # exact: no float32 detour above 2**24
            lhs, rhs = _align_literals(l_lit, rhs)
            return (self._eval_expr_arrow(args[0], table) if lhs is l_lit else lhs), rhs
        if r_lit is not None and l_lit is None:
            lhs = self._eval_expr_arrow(args[0], table)
            if isinstance(r_lit, int) and pa.types.is_integer(lhs.type):
                return lhs, _npscalar(r_lit)
            lhs, rhs = _align_literals(lhs, r_lit)
            return lhs, (self._eval_expr_arrow(args[1], table) if rhs is r_lit else rhs)
        return _double_vs_int(args, *_align_temporal(self._eval_expr_arrow(args[0], table), self._eval_expr_arrow(args[1], table)))

    def _eval_expr_arrow(self, expr, table):
        """Evaluate expr on an Arrow table, returning a pa.Array."""
        from .lazy_expr import Expr as _Expr
        op, args = expr.op, expr.args
        if op == "col":
            col_arr = table.column(args[0])
            if pa.types.is_dictionary(col_arr.type):
                col_arr = _decode_dict(col_arr)
            if isinstance(col_arr, pa.ChunkedArray):
                # Single-chunk: return underlying Array directly — no 50ms copy!
                if len(col_arr.chunks) == 1:
                    return col_arr.chunks[0]
                return _combine(col_arr)
            return col_arr
        if op == "lit":
            val = args[0]
            n = len(table)
            if isinstance(val, (np.datetime64, np.bool_, np.integer)):      # a NumPy scalar keeps its own type, also on 0 rows
                return _npa(np.full(n, val))
            if isinstance(val, (int, float)):
                return _npa(np.full(
                    n, val, dtype=np.float64 if getattr(_PRECISE, 'on', False) or isinstance(val, np.float64) else np.float32))
            if isinstance(val, (str, datetime.date)):          # (no rows: still a string / date32, not null)
                return _npa([val] * n, type=_npscalar(val).type)
            return _npa([val] * n)
        if op == "mod":
            return _modulo(*self._arith_operands(args, table), decimal=len(args) > 2)
        if op in ("idiv", "pow"):
            return SQL_MATH[op](*self._arith_operands(args, table))
        if op in SQL_MATH:                                       # sqrt, ln, nullify: one argument
            return SQL_MATH[op](*(self._eval_expr_arrow(a, table) for a in args))
        if op in ("add", "sub", "mul", "div"):
            lhs, rhs = self._arith_operands(args, table)
            if op == "div":
                # SQL `/` is true division, in float64 like DuckDB's (an int64 past 2^53 rounds, it does not raise)
                if pa.types.is_integer(lhs.type):
                    lhs = pc.cast(lhs, pa.float64(), safe=False)
                if pa.types.is_integer(rhs.type):
                    rhs = pc.cast(rhs, pa.float64(), safe=False)
                return pc.divide(lhs, rhs)
            if (op == "sub" and getattr(lhs, "type", None) == pa.date32()
                    and getattr(rhs, "type", None) in (pa.date32(), pa.int32())):
                # DATE - DATE is the number of days (BIGINT); an int32 column holds days since 1970 (F-115)
                return pc.cast(pc.subtract(pc.cast(lhs, pa.int32()), pc.cast(rhs, pa.int32())), pa.int64())
            return _checked_arith(op, lhs, rhs)
        if op in _DICT_PRED_OPS:
            native = _dict_predicate(expr, table)
            if native is not None:
                return native
        if op in ("eq", "ne"):
            lhs_expr, rhs_expr = args[0], args[1]
            if (self._session_device == "gpu" and self._aot_gpu is not None
                    and lhs_expr.op == "col" and rhs_expr.op == "lit"
                    and isinstance(rhs_expr.args[0], str)):
                col_arr = self._eval_expr_arrow(lhs_expr, table)
                bool_mask = (self._gpu_mask("string filter", col_arr,
                                            lambda: self._aot_gpu.utf8_equal_mask(col_arr, rhs_expr.args[0]))
                             if pa.types.is_string(col_arr.type) else None)
                if bool_mask is not None:
                    if op == "ne":
                        bool_mask = np.logical_not(bool_mask)
                        if col_arr.null_count:
                            bool_mask &= _np_of(pc.is_valid(col_arr), zero_copy_only=False)
                    return _npa(bool_mask, type=pa.bool_())
            return _PC_CMP_OPS[op](*self._cmp_operands(args, table))
        if op in _PC_CMP_OPS:
            if op in ("and", "or"):
                return _PC_CMP_OPS[op](self._eval_expr_arrow(args[0], table),
                                       self._eval_expr_arrow(args[1], table))
            return _PC_CMP_OPS[op](*self._cmp_operands(args, table))
        if op == "not":
            return pc.invert(self._eval_expr_arrow(args[0], table))
        if op == "is_null":
            return pc.is_null(self._eval_expr_arrow(args[0], table))
        if op == "isin":
            col_arr = self._eval_expr_arrow(args[0], table)
            if (self._session_device == "gpu" and self._aot_gpu is not None
                    and pa.types.is_string(col_arr.type) and args[1]
                    and all(isinstance(value, str) for value in args[1])):
                mask = self._gpu_mask("string filter", col_arr, lambda: self._aot_gpu.utf8_isin_mask(col_arr, args[1]))
                if mask is not None:
                    return _npa(mask, type=pa.bool_())
            return _is_in(col_arr, args[1])
        if op == "str_slice":
            return _str_slice(self._eval_expr_arrow(args[0], table), args[1], args[2])
        if op == "startswith":
            col_arr = self._eval_expr_arrow(args[0], table)
            if (self._session_device == "gpu" and self._aot_gpu is not None
                    and pa.types.is_string(col_arr.type)):
                mask = self._gpu_mask("string filter", col_arr,
                                      lambda: self._aot_gpu.utf8_startswith_mask(col_arr, args[1]))
                if mask is not None:
                    return _npa(mask, type=pa.bool_())
            return pc.starts_with(col_arr, pattern=args[1])
        if op == "contains":
            col_arr = self._eval_expr_arrow(args[0], table)
            if (self._session_device == "gpu" and self._aot_gpu is not None
                    and pa.types.is_string(col_arr.type)):
                mask = self._gpu_mask("string filter", col_arr,
                                      lambda: self._aot_gpu.utf8_contains_mask(col_arr, args[1]))
                if mask is not None:
                    return _npa(mask, type=pa.bool_())
            return pc.match_substring(col_arr, pattern=args[1])
        if op == "like":
            from .str_patterns import match_like
            return match_like(self._eval_expr_arrow(args[0], table), args[1], args[2], args[3])
        if op == "year_days":
            return year_days_arrow(self._eval_expr_arrow(args[0], table))
        if op == "year":
            col_arr = self._eval_expr_arrow(args[0], table)
            if col_arr.type in (pa.int32(), pa.int64()):
                return pc.cast(pc.divide(col_arr, _npscalar(10000, type=pa.int32())), pa.int32())
            return pc.year(col_arr)
        if op in ("and", "__and__"):
            return pc.and_kleene(self._eval_expr_arrow(args[0], table),
                                 self._eval_expr_arrow(args[1], table))
        if op in ("or", "__or__"):
            return pc.or_kleene(self._eval_expr_arrow(args[0], table),
                                self._eval_expr_arrow(args[1], table))
        if op == "case_when":
            # the common type of the branches (integers stay integers, numbers mixed are float64 on both
            # devices: float32 would lose integers above 2**24 and round float64 values, F-022)
            return case_when_guarded(self._eval_expr_arrow, args, table)
        if op == "coalesce":
            return coalesce_arrow(*branch_values(args, lambda a: self._eval_expr_arrow(a, table)))
        if op == "abs":
            return abs_arrow(self._eval_expr_arrow(args[0], table))
        if op == "add_us":
            return add_interval_arrow(self._eval_expr_arrow(args[0], table), args[1])
        if op == "cast":
            return cast_arrow(self._eval_expr_arrow(args[0], table), *args[1:])
        if op == "f32":
            return cast_arrow(self._eval_expr_arrow(args[0], table), "float32")
        # ── Window / analytic functions (global scope — whole table, no partition) ─
        if op == "row_number":
            return _npa(np.arange(1, table.num_rows + 1, dtype=np.float64))
        if op == "rank":
            return _npa(_window_rank(self._eval_expr_arrow(args[0], table)))
        if op == "dense_rank":
            return _npa(_window_dense_rank(self._eval_expr_arrow(args[0], table)))
        if op == "cum_sum":
            a = self._eval_expr_arrow(args[0], table)
            out, nul = _cum_sum_skip_null(_np_of(a, zero_copy_only=False).astype(np.float64), _np_of(pc.is_valid(a)))
            return _npa(np.ma.array(out, mask=nul)) if nul.any() else _npa(out)
        if op in ("lag", "lead"):
            src = np.full(table.num_rows, -1, dtype=np.int64)
            _shift_rows(src, np.arange(table.num_rows), args, op == "lead")
            return _take_shifted(self._eval_expr_arrow(args[0], table), src, args)
        if op == "window":
            return self._eval_window_arrow(args[0], args[1], table)
        raise NotImplementedError(f"_eval_expr_arrow: unsupported op '{op}'")

    def _extract_derived_cols(self, plan):
        """Rewrite case_when/isin/startswith in agg/project exprs as derived col refs.

        Returns (rewritten_plan, derived_specs) where derived_specs is a list of
        (col_name, original_expr) pairs to be evaluated in PyArrow before the graph.
        """
        from .lazy_expr import Expr as _Expr
        derived_specs = []

        def _rewrite_expr(expr):
            if not CustomOpsCompiler._needs_precompute(expr):
                return expr
            if expr.op in ("case_when", "isin", "startswith", "contains", "like", "is_null", "coalesce", "abs", "cast", "f32", "add_us",
                           *_ARROW_ONLY_OPS):
                name = f"__cw_{len(derived_specs)}__"
                derived_specs.append((name, expr))
                new_expr = _Expr("col", name)
                new_expr._alias = expr._alias
                return new_expr
            new_args = [
                _rewrite_expr(a) if isinstance(a, _Expr) else a
                for a in expr.args
            ]
            new_expr = _Expr(expr.op, *new_args)
            new_expr._alias = expr._alias
            return new_expr

        def _rewrite_plan(p):
            if isinstance(p, Scan): return p
            if isinstance(p, Aggregate):
                new_aggs = [_rewrite_expr(e) for e in p.aggs]
                return Aggregate(_rewrite_plan(p.input), p.group_by, new_aggs)
            if isinstance(p, Project):
                new_exprs = [_rewrite_expr(e) for e in p.exprs]
                return Project(_rewrite_plan(p.input), new_exprs)
            if isinstance(p, Filter):
                return Filter(_rewrite_plan(p.input), p.predicate)
            if isinstance(p, (Sort, Limit, Distinct, Tail)):
                import copy
                new_node = copy.copy(p)
                new_node.input = _rewrite_plan(p.input)
                return new_node
            if isinstance(p, Join):
                return Join(_rewrite_plan(p.left), _rewrite_plan(p.right),
                            p.left_on, p.right_on, p.how)
            if hasattr(p, "input"):
                p.input = _rewrite_plan(p.input)
            return p

        new_plan = _rewrite_plan(plan)
        return new_plan, derived_specs


    def _compute_global_agg_pyarrow(self, table: "pa.Table", agg_node) -> "pa.Table":
        """Evaluate a global (ungrouped) aggregate using PyArrow/numpy.

        Called when the plan has an Aggregate with no group_by keys.  Covers
        sum / min / max / mean / count with arbitrary expression trees (mul, add,
        case_when, startswith, isin, …) via ``_eval_expr_arrow``.

        Returns a single-row pa.Table with one column per aggregation.
        """
        import pyarrow as _pa
        result_cols = {}
        for i, expr in enumerate(agg_node.aggs):
            name = expr._alias or f"agg_{i}"
            op   = expr.op
            if op in ("sum", "min", "max", "mean"):
                inner_arr = self._eval_expr_arrow(expr.args[0], table)
                arr_np    = _np_of(inner_arr, zero_copy_only=False).astype("float64")
                if len(arr_np) == 0:                     # SQL: sum/min/max/mean over no rows is NULL
                    result_cols[name] = _npa(np.ma.masked_all(1, dtype=np.float64), type=_pa.float64())
                    continue
                if   op == "sum":  val = float(arr_np.sum())
                elif op == "min":  val = float(np.fmin.reduce(arr_np))    # NaN is above every number (F-070): min skips it
                elif op == "max":  val = float(arr_np.max())              # ... and max is NaN if there is one
                else:              val = float(arr_np.mean())   # mean
                result_cols[name] = _npa([val], type=_pa.float64())
            elif op == "count":
                result_cols[name] = _npa([len(table)], type=_pa.int64())
            else:
                raise NotImplementedError(
                    f"_compute_global_agg_pyarrow: unsupported agg op '{op}'"
                )
        return _pa.table(result_cols)

    # ── Masked global aggregation fast path ────────────────────────────────────

    @staticmethod
    def _is_simple_col_product(expr) -> "Optional[tuple[str, str]]":
        """Return (col_a, col_b) if expr is col_a * col_b, else None."""
        if expr.op == "mul":
            a, b = expr.args[0], expr.args[1]
            if a.op == "col" and b.op == "col":
                return (a.args[0], b.args[0])
        return None

    @staticmethod
    def _is_simple_col(expr) -> "Optional[str]":
        """Return the column name if expr is just col('name'), else None."""
        if expr.op == "col":
            return expr.args[0]
        return None

    @staticmethod
    def _flatten_and(expr) -> list:
        if expr.op == "and":
            return (CustomOpsCompiler._flatten_and(expr.args[0])
                    + CustomOpsCompiler._flatten_and(expr.args[1]))
        return [expr]

    @classmethod
    def _range5_product_spec(cls, predicates, agg_node):
        """Recognize a five-comparison range filter feeding sum(col * col)."""
        if len(agg_node.aggs) != 1 or agg_node.aggs[0].op != "sum":
            return None
        product = cls._is_simple_col_product(agg_node.aggs[0].args[0])
        if product is None:
            return None
        terms = []
        for predicate in predicates:
            terms.extend(cls._flatten_and(predicate))
        comparisons = {}
        for term in terms:
            if term.op not in ("ge", "gt", "le", "lt"):
                return None
            lhs, rhs = term.args
            if lhs.op != "col" or rhs.op != "lit" or not isinstance(rhs.args[0], (int, float)):
                return None
            comparisons[(lhs.args[0], term.op)] = rhs.args[0]
        columns = {name for name, _ in comparisons}
        ranged = [name for name in columns if (name, "ge") in comparisons and (name, "lt") in comparisons]
        float_ranged = [name for name in columns if (name, "ge") in comparisons and (name, "le") in comparisons]
        upper = [name for name in columns if (name, "lt") in comparisons and name not in ranged]
        if len(ranged) != 1 or len(float_ranged) != 1 or len(upper) != 1 or len(terms) != 5:
            return None
        return (
            product,
            ranged[0], comparisons[(ranged[0], "ge")], comparisons[(ranged[0], "lt")],
            float_ranged[0], comparisons[(float_ranged[0], "ge")], comparisons[(float_ranged[0], "le")],
            upper[0], comparisons[(upper[0], "lt")],
        )

    def _gpu_mask(self, name, col_arr, gpu_fn):
        """A bool numpy mask from a GPU string kernel, or None when the piece left the GPU (Arrow does it)."""
        mask = gpu_budget.run_piece(name, col_arr.nbytes + 8 * len(col_arr), gpu_fn, lambda: None,
                                    shape=(len(col_arr), col_arr.nbytes))
        return None if mask is None else mask.astype(np.bool_, copy=False)

    def _masked_on_gpu(self, name, gpu_fn, cpu_fn, *arrays):
        """A masked global aggregate on the GPU, rerun by the CPU AOT kernel when the GPU is too small."""
        if cpu_fn is None:
            return gpu_fn(*arrays)
        return gpu_budget.run_piece(name, sum(a.nbytes for a in arrays) + 4096, lambda: gpu_fn(*arrays),
                                    lambda: cpu_fn(*arrays), shape=(len(arrays[-1]), len(arrays), arrays[0].dtype.str))

    def _run_masked_global_sum(
        self, arr_f32: np.ndarray, mask_np: np.ndarray, N: int
    ) -> float:
        """Execute the masked_global_sum Mojo kernel and return a Python float."""
        if self._cpu_aot_fallback():
            return self._aot.masked_global_sum(arr_f32, mask_np)
        if self._session_device == "gpu" and self._aot_gpu is not None:
            return self._masked_on_gpu("masked_global_sum", self._aot_gpu.masked_global_sum_f32, self._aot and self._aot.masked_global_sum, arr_f32, mask_np)
        cache_key = ("_masked_global_sum_kernel", N, self._session_device)
        if cache_key not in _MODEL_CACHE:
            mg_graph = Graph(
                name="mxframe_masked_global_sum",
                input_types=[
                    TensorType(DType.float32, [N], self._device_ref),
                    TensorType(DType.int32, [N], self._device_ref),
                ],
                custom_extensions=[Path(self.kernels_path)],
            )
            with mg_graph:
                out_node = ops.custom(
                    name="masked_global_sum",
                    values=[mg_graph.inputs[0], mg_graph.inputs[1]],
                    out_types=[TensorType(DType.float32, [1], self._device_ref)],
                    device=self._device_ref,
                )[0]
                mg_graph.output(out_node)
            mg_model = self._session.load(mg_graph)
            _MODEL_CACHE[cache_key] = (mg_model, ["_sum"])

        mg_model, _ = _MODEL_CACHE[cache_key]
        if self._session_device == "gpu":
            val_buf, _ = self._to_gpu_input(arr_f32)
            msk_buf, _ = self._to_gpu_input(mask_np)
            (result_tensor,) = mg_model.execute(val_buf, msk_buf)
        else:
            (result_tensor,) = mg_model.execute(arr_f32, mask_np)
        return float(_np_of(result_tensor).flat[0])

    def _run_masked_global_sum_product(
        self, a_f32: np.ndarray, b_f32: np.ndarray, mask_np: np.ndarray, N: int
    ) -> float:
        """Execute the masked_global_sum_product Mojo kernel (sum(a*b where mask)).

        True single-pass fused kernel: reads two input columns + mask and
        computes sum(a[i]*b[i]) for passing rows, with zero intermediate
        allocation.  Faster than pc.multiply(full) + masked_sum for Q6-class
        queries with low selectivity.
        """
        if self._cpu_aot_fallback():
            return self._aot.masked_global_sum_product(a_f32, b_f32, mask_np)
        if self._session_device == "gpu" and self._aot_gpu is not None:
            return self._masked_on_gpu("masked_global_sum_product", self._aot_gpu.masked_global_sum_product_f32, self._aot and self._aot.masked_global_sum_product, a_f32, b_f32, mask_np)
        cache_key = ("_masked_global_sum_product_kernel", N, self._session_device)
        if cache_key not in _MODEL_CACHE:
            mg_graph = Graph(
                name="mxframe_masked_global_sum_product",
                input_types=[
                    TensorType(DType.float32, [N], self._device_ref),  # col_a
                    TensorType(DType.float32, [N], self._device_ref),  # col_b
                    TensorType(DType.int32, [N], self._device_ref),    # mask
                ],
                custom_extensions=[Path(self.kernels_path)],
            )
            with mg_graph:
                out_node = ops.custom(
                    name="masked_global_sum_product",
                    values=[mg_graph.inputs[0], mg_graph.inputs[1], mg_graph.inputs[2]],
                    out_types=[TensorType(DType.float32, [1], self._device_ref)],
                    device=self._device_ref,
                )[0]
                mg_graph.output(out_node)
            mg_model = self._session.load(mg_graph)
            _MODEL_CACHE[cache_key] = (mg_model, ["_sum_product"])

        mg_model, _ = _MODEL_CACHE[cache_key]
        if self._session_device == "gpu":
            a_buf, _ = self._to_gpu_input(a_f32)
            b_buf, _ = self._to_gpu_input(b_f32)
            msk_buf, _ = self._to_gpu_input(mask_np)
            (result_tensor,) = mg_model.execute(a_buf, b_buf, msk_buf)
        else:
            (result_tensor,) = mg_model.execute(a_f32, b_f32, mask_np)
        return float(_np_of(result_tensor).flat[0])

