    @property
    def _session(self):
        """Lazy GPU session: created on first MAX Graph call (after AOT fast paths skip)."""
        return self.session

    def _cpu_aot_fallback(self) -> bool:
        """Use the CPU AOT kernels: on the cpu device, or on the gpu device when the GPU AOT
        library is unavailable (better than compiling a MAX Graph for host arrays)."""
        if self._aot is None:
            return False
        return self._session_device == "cpu" or self._aot_gpu is None

    def _cpu_aot_active(self) -> bool:
        return self._session_device == "cpu" and self._aot is not None

    def _eval_expr_f64(self, expr, table: pa.Table) -> np.ndarray:
        """Evaluate a numeric expression with float32 columns widened to float64
        (CPU aggregation path); returns a contiguous float64 ndarray."""
        cols = {}
        for name in _expr_col_names(expr):
            c = table.column(name)
            cols[name] = pc.cast(c, pa.float64()) if pa.types.is_float32(c.type) else c
        if not cols:
            # literal-only expression: keep the row count so literals broadcast to every row
            cols["__rows__"] = _npa(np.zeros(table.num_rows, dtype=np.int8))
        sub = pa.table(cols)
        prev = getattr(_PRECISE, "on", False)
        _PRECISE.on = True
        try:
            res = self._eval_expr_arrow(expr, sub)
        finally:
            _PRECISE.on = prev
        return np.ascontiguousarray(_np_of(res, zero_copy_only=False), dtype=np.float64)

    def _get_col_agg(self, col_name: str, table: pa.Table) -> "Optional[np.ndarray]":
        """Column as a contiguous array for an aggregation kernel.

        GPU sessions: float32 (as before).  CPU AOT: float32 columns stay float32
        (zero-copy; the kernels accumulate in float64), everything else is widened
        to float64 instead of being squeezed down to float32."""
        if not self._cpu_aot_active():
            return self._get_col_as_f32(col_name, table)
        arr = table.column(col_name)
        if isinstance(arr, pa.ChunkedArray):
            arr = arr.chunks[0] if len(arr.chunks) == 1 else _combine(arr)
        view = self._arrow_array_to_numpy_view(arr)
        if view is None:
            view = _np_of(arr, zero_copy_only=False)
        out = view if view.dtype == np.float32 else view.astype(np.float64, copy=False)
        return out if out.flags["C_CONTIGUOUS"] else np.ascontiguousarray(out)

    def _get_col_as_f32(self, col_name: str, table: pa.Table) -> "Optional[np.ndarray]":
        """Get a column as a contiguous float32 numpy array, preferring zero-copy."""
        arr = table.column(col_name)
        if isinstance(arr, pa.ChunkedArray):
            arr = arr.chunks[0] if len(arr.chunks) == 1 else _combine(arr)
        view = self._arrow_array_to_numpy_view(arr)
        if view is not None:
            out = view.astype(np.float32, copy=False)
        else:
            out = _np_of(arr, zero_copy_only=False).astype(np.float32)
        return out if out.flags["C_CONTIGUOUS"] else np.ascontiguousarray(out)

    def _compute_masked_global_agg(self, plan, agg_node) -> "Optional[pa.Table]":
        """Fast path for Filter → GlobalAgg using fused Mojo masked kernels.

        Dispatch per aggregation (in priority order):
          1. count(*)                → int(mask.sum())
          2. min/max(col)            → masked_global_min/max GPU kernel
          3. sum(col)                → masked_global_sum GPU kernel
          4. sum(col_a * col_b)      → masked_global_sum_product GPU kernel
          5. sum/mean(any_expr)      → _eval_expr_arrow → masked_global_sum GPU kernel
             Handles a*(1-b), a*(1-b)*(1+c), case_when, startswith, isin, …
             Expression eval uses Arrow/NumPy; the SUM reduction runs on GPU.

        Returns None to signal fall-back to the PyArrow path.
        """
        for expr in agg_node.aggs:
            if expr.op not in ("sum", "mean", "count", "min", "max"):
                return None
            # min/max on complex expressions (products, case_when) still fall back —
            # no fused min/max kernel for arbitrary expressions yet.
            if expr.op in ("min", "max"):
                inner = expr.args[0]
                if self._is_simple_col(inner) is None:
                    return None
            # sum/mean: any inner expression handled via _eval_expr_arrow below.

        try:
            original_scan = self._find_scan(plan)
        except Exception:
            return None

        table = original_scan.table
        N = table.num_rows

        predicates = self._collect_predicates(plan)

        range5_spec = self._range5_product_spec(predicates, agg_node)
        if (range5_spec is not None and self._session_device == "gpu"
                and self._aot_gpu is not None):
            try:
                (product, int_name, int_lo, int_hi, float_name, float_lo,
                 float_hi, upper_name, upper_hi) = range5_spec
                r5 = (self._get_col_as_f32(product[0], table), self._get_col_as_f32(product[1], table),
                      np.ascontiguousarray(_np_of(table.column(int_name), zero_copy_only=False), dtype=np.int32),
                      self._get_col_as_f32(float_name, table), self._get_col_as_f32(upper_name, table))
                value = gpu_budget.run_piece(          # out of GPU memory: the general path below
                    "range5 sum-product", sum(a.nbytes for a in r5) + 4096,
                    lambda: self._aot_gpu.range5_sum_product_f32(
                        *r5, int(int_lo), int(int_hi), float(float_lo), float(float_hi), float(upper_hi)),
                    gpu_budget.leave_gpu, shape=(N, len(r5)), left="left the fused GPU path")
                if value == 0.0:
                    raise ValueError("no row passed: the general path below returns SQL's NULL")
                name = agg_node.aggs[0]._alias or "agg_0"
                return pa.table({name: _npa([value], type=pa.float64())})
            except MemoryError:
                if gpu_budget.strict():
                    raise
            except Exception:
                pass

        # Compute mask as int32 numpy — no .filter() allocation.
        mask_np: Optional[np.ndarray] = None
        if predicates:
            try:
                combined = None
                for pred in predicates:
                    m = self._eval_predicate(pred, table)
                    combined = m if combined is None else pc.and_(combined, m)
                mask_np = _np_of(combined, zero_copy_only=False).astype(np.int32)
                if not mask_np.flags["C_CONTIGUOUS"]:
                    mask_np = np.ascontiguousarray(mask_np)
            except Exception:
                return None

        n_pass = int(mask_np.sum()) if mask_np is not None else N
        if n_pass == 0:
            result_cols = {}
            for i, expr in enumerate(agg_node.aggs):
                name = expr._alias or f"agg_{i}"
                result_cols[name] = (
                    _npa([0], type=pa.int64()) if expr.op == "count"
                    else _npa(np.ma.masked_all(1, dtype=np.float64), type=pa.float64())   # SQL: NULL over no rows
                )
            return pa.table(result_cols)

        if mask_np is None:
            mask_np = np.ones(N, dtype=np.int32)

        result_cols = {}
        for i, expr in enumerate(agg_node.aggs):
            name = expr._alias or f"agg_{i}"
            try:
                if expr.op == "count":
                    result_cols[name] = _npa([n_pass], type=pa.int64())
                    continue

                inner = expr.args[0]
                product_cols = self._is_simple_col_product(inner)
                simple_col   = self._is_simple_col(inner)

                if expr.op in ("min", "max"):
                    # min/max only supported on simple single columns (not products)
                    if simple_col is None:
                        return None
                    arr_f32 = self._get_col_agg(simple_col, table)
                    if arr_f32 is None:
                        return None
                    if expr.op == "min":
                        val = self._run_masked_global_min(arr_f32, mask_np, N)
                    else:
                        val = self._run_masked_global_max(arr_f32, mask_np, N)
                    result_cols[name] = _npa([float(val)], type=pa.float64())
                    continue

                if product_cols is not None:
                    # sum(col_a * col_b) — fused single-pass kernel, no alloc
                    col_a_name, col_b_name = product_cols
                    a_f32 = self._get_col_agg(col_a_name, table)
                    b_f32 = self._get_col_agg(col_b_name, table)
                    if a_f32 is None or b_f32 is None:
                        return None
                    sum_val = self._run_masked_global_sum_product(a_f32, b_f32, mask_np, N)

                elif simple_col is not None:
                    # sum(col) — single-column masked sum
                    arr_f32 = self._get_col_agg(simple_col, table)
                    if arr_f32 is None:
                        return None
                    sum_val = self._run_masked_global_sum(arr_f32, mask_np, N)

                else:
                    # General expression path: evaluate inner with Arrow (handles
                    # a*(1-b), a*(1-b)*(1+c), case_when, startswith, isin, etc.),
                    # then SUM reduction on GPU via the masked_global_sum kernel.
                    if self._cpu_aot_active():
                        arr_f32 = self._eval_expr_f64(inner, table)      # float64 end to end
                    else:
                        inner_arr = self._eval_expr_arrow(inner, table)
                        arr_f32 = _np_of(inner_arr, zero_copy_only=False).astype(np.float32)
                        if not arr_f32.flags["C_CONTIGUOUS"]:
                            arr_f32 = np.ascontiguousarray(arr_f32)
                    sum_val = self._run_masked_global_sum(arr_f32, mask_np, N)

                if expr.op == "sum":
                    result_cols[name] = _npa([float(sum_val)], type=pa.float64())
                else:  # mean
                    mean_val = float(sum_val) / n_pass if n_pass > 0 else 0.0
                    result_cols[name] = _npa([mean_val], type=pa.float64())

            except Exception:
                return None

        return pa.table(result_cols)

    def _eval_window_arrow(self, inner_expr, spec, table: pa.Table) -> pa.Array:
        """Evaluate a partitioned window expression, returning one value per original row.

        *spec* is a (partition_by, order_by, descending) tuple produced by
        ``Expr.over()``.  The result is always float64.

        Supported inner ops: sum, mean, min, max (broadcast group agg),
        rank, dense_rank, row_number, lag, lead, cum_sum.
        """
        partition_by, order_by, descending = spec
        n = table.num_rows
        result = np.empty(n, dtype=np.float64)

        # Build {key_tuple: [row_indices]} map
        if partition_by:
            gid, _ = _np_group_ids(pa.table({c: table.column(c) for c in partition_by}),
                                   partition_by)
            order = np.argsort(gid, kind="stable")
            bounds = np.flatnonzero(np.diff(gid[order])) + 1
            groups = {i: part.tolist() for i, part in enumerate(np.split(order, bounds))} if n else {}
        else:
            groups = {(): list(range(n))}

        okeys = [_order_codes(table.column(c), descending) for c in order_by] if order_by else []
        null_out = np.zeros(n, dtype=bool)          # rows whose window value is NULL
        shift_src = np.full(n, -1, dtype=np.int64)  # lag / lead: source row per row, -1 for none
        shifted = None

        def values(e, sub):
            a = self._eval_expr_arrow(e, sub)
            return _np_of(a, zero_copy_only=False).astype(np.float64), _np_of(pc.is_valid(a))

        for row_indices in groups.values():
            ri = np.asarray(row_indices, dtype=np.int64)
            if okeys:
                ri = ri[np.lexsort([k[ri] for k in reversed(okeys)])]    # stable: ties keep row order
            sub = pc.take(table, _npa(ri))
            ordered_indices = ri

            op   = inner_expr.op
            args = inner_expr.args
            m    = len(ordered_indices)

            if op in ("min", "max"):
                arr, valid = values(args[0], sub)
                ok = arr[valid]                          # NULL is not NaN: aggregate valid values only
                if ok.size == 0:
                    val = np.zeros(m)
                    null_out[ordered_indices] = True
                else:                                    # MAX is NaN if any is (numpy propagates)
                    val = np.full(m, _min_skip_nan(ok) if op == "min" else ok.max())
            elif op in ("sum", "mean"):
                arr, valid = values(args[0], sub)
                ok = arr[valid]                          # NULLs are skipped; none valid gives NULL
                if ok.size == 0:
                    val = np.zeros(m)
                    null_out[ordered_indices] = True
                else:
                    val = np.full(m, ok.sum() if op == "sum" else ok.mean())
            elif op == "rank":
                val = _window_rank(self._eval_expr_arrow(args[0], sub), descending)
            elif op == "dense_rank":
                val = _window_dense_rank(self._eval_expr_arrow(args[0], sub), descending)
            elif op == "row_number":
                val = np.arange(1, m + 1, dtype=np.float64)
            elif op == "cum_sum":
                arr, valid = values(args[0], sub)
                val, nul = _cum_sum_skip_null(arr, valid)
                null_out[ordered_indices[nul]] = True
            elif op in ("lag", "lead"):
                _shift_rows(shift_src, ordered_indices, args, op == "lead")
                shifted = op
                continue
            else:
                raise NotImplementedError(
                    f"_eval_window_arrow: unsupported inner op '{op}'"
                )

            result[ordered_indices] = val

        if shifted:                       # lag / lead keep the input's type and its NULLs
            return _take_shifted(self._eval_expr_arrow(inner_expr.args[0], table), shift_src, inner_expr.args)
        if null_out.any():
            return _npa(np.ma.array(result, mask=null_out))
        return _npa(result, type=pa.float64())

    def _compute_cache_key(self, plan, all_names, all_arrays, n_groups, optimizer_trace=None):
        """Compute a hashable cache key for the compiled graph model.

        Key components:
        - plan_sig: structural signature of the logical plan (ops, column refs, literals)
        - input_sig: (name, dtype, shape) per input tensor -- determines graph input types
        - n_groups: number of groups (affects output shapes in grouped path)
        - device: CPU vs GPU (different kernel dispatch + output shapes)
        """
        plan_sig = plan.signature()
        input_sig = tuple(
            (n, str(all_arrays[n].dtype), all_arrays[n].shape[0]) for n in all_names
        )
        optimizer_sig = tuple(optimizer_trace or ())
        return (plan_sig, input_sig, n_groups, self._session_device, optimizer_sig)

    def _eval_group_key(self, expr, table: pa.Table):
        """Evaluate a derived group key.  Integer arithmetic on integer columns stays integer
        (the generic evaluator widens literals to float32, which would turn ``k*2+j`` keys
        into floats and lose exactness above 2**24)."""
        arr = self._eval_int_expr(expr, table)
        return arr if arr is not None else self._eval_expr_arrow(expr, table)

    def _eval_int_expr(self, expr, table: pa.Table):
        """add/sub/mul over integer columns and Python-int literals, as an int array; else None."""
        if expr.op == "col":
            a = self._eval_expr_arrow(expr, table)
            return a if pa.types.is_integer(a.type) else None
        if expr.op == "lit":
            return expr.args[0] if isinstance(expr.args[0], int) and not isinstance(expr.args[0], bool) else None
        if expr.op in ("add", "sub", "mul") and len(expr.args) == 2:
            l = self._eval_int_expr(expr.args[0], table)
            r = self._eval_int_expr(expr.args[1], table)
            if l is None or r is None or (isinstance(l, int) and isinstance(r, int)):
                return None
            if isinstance(l, int):
                l = _npscalar(l, type=r.type)
            if isinstance(r, int):
                r = _npscalar(r, type=l.type)
            try:
                return _checked_arith(expr.op, l, r)
            except OverflowError:              # overflow in the column's own width
                wide = pa.int64()
                return _checked_arith(expr.op, pc.cast(l, wide) if isinstance(l, pa.Array) else l,
                                      pc.cast(r, wide) if isinstance(r, pa.Array) else r)
        return None

    def _count_distinct_by_key(self, plan):
        """``Aggregate(Distinct(two columns a, b), group_by=[a], aggs=[count(b) or count(*)])``
        (TPC-H Q21's suppliers per order) as one native pass when ``a`` is sorted (F-023): no
        distinct table, no second group-by. Returns a Scan of the result, an equivalent plan when
        the native call declines (the distinct input computed once), or None for other shapes.
        The plan's dictionary columns arrive here as codes (io_parquet keeps both columns of this
        shape encoded, F-046h): the native call counts codes, every other path decodes them first."""
        from .io_parquet import count_distinct_shape
        if not count_distinct_shape(plan):
            return None
        k, agg = plan.group_by[0], plan.aggs[0]
        key, arg = k.args[0], agg.args[0]
        table = self._count_distinct_input(plan.input.input)
        names = table.column_names
        other = [c for c in names if c != key]

        def equivalent():
            plain = _decode_deferred_cols(table, set(names))
            return Aggregate(Scan(self.compile_and_run(Distinct(Scan(plain), None))), plan.group_by, plan.aggs)

        if (_native_exec is None or not _native_exec.enabled()
                or getattr(self, "_device_arg", None) != "cpu"):
            return equivalent()            # GPU / auto / executor off: the distinct table as before
        if len(names) != 2 or len(other) != 1 or (arg.op == "col" and arg.args[0] != other[0]):
            return equivalent()
        try:
            res = _native_exec.try_count_distinct(self, table, key, other[0], agg._alias)
        except Exception as exc:          # never fail the query: the equivalent plan answers
            res = _native_exec.swallowed(exc, "count distinct")
        if res is None:
            return equivalent()
        return Scan(res)

    def _count_distinct_input(self, project):
        """The (a, b) rows under a count-distinct, with dictionary columns still as codes when
        they come straight from a scan or a join's output (a bare Project would decode them)."""
        node = self._materialize_joins(project)
        if isinstance(node, Scan):
            return node.table
        if (_native_exec is not None and isinstance(node, Project)
                and all(isinstance(e, Expr) and e.op == "col" and e._alias in (None, e.args[0]) for e in node.exprs)):
            names = [e.args[0] for e in node.exprs]
            src, preds = self._scan_of(node)
            if src is not None and all(n in src.table.column_names for n in names):
                t = src.table
                if not preds:
                    return t.select(names)
                keep = {n for n in names if pa.types.is_dictionary(t.schema.field(n).type)}
                try:
                    got = _native_exec.try_filter(self, t, preds, set(names), keep_dict=keep)
                except Exception as exc:
                    got = _native_exec.swallowed(exc, "leaf filter")
                if got is not None:
                    return got.select(names)
        return self.compile_and_run(node)

    def _lower_row_ops(self, plan, top: bool = True):
        """Execute Sort/Limit/Distinct/Tail nodes that sit below a Filter/Project/Aggregate.

        Ops at the top of the plan stay (they are applied to the final result); below another
        operator they decide which rows it sees, so they are computed first and replaced by a
        Scan of their result."""
        if isinstance(plan, (Sort, Limit, Distinct, Tail)):
            inner = self._lower_row_ops(plan.input, top)
            if isinstance(plan, Sort):
                node = Sort(inner, plan.by, plan.descending)
            elif isinstance(plan, Limit):
                node = Limit(inner, plan.n, plan.offset)
            elif isinstance(plan, Distinct):
                node = Distinct(inner, plan.subset)
            else:
                node = Tail(inner, plan.n)
            return node if top else Scan(self.compile_and_run(node))
        if isinstance(plan, Filter):
            return Filter(self._lower_row_ops(plan.input, False), plan.predicate)
        if isinstance(plan, Project):
            return Project(self._lower_row_ops(plan.input, False), plan.exprs)
        if isinstance(plan, Aggregate):
            counted = self._count_distinct_by_key(plan)
            if counted is not None:
                return counted
            return Aggregate(self._lower_row_ops(plan.input, False), plan.group_by, plan.aggs)
        return plan

    @staticmethod
    def _contains_aggregate(plan) -> bool:
        """True when an Aggregate sits anywhere in the single-input chain of ``plan`` (Joins are
        materialized before this is asked, and their sides are computed on their own)."""
        while plan is not None:
            if isinstance(plan, Aggregate):
                return True
            plan = getattr(plan, "input", None)
        return False

    def _fused_join_aggregate(self, plan):
        """``[Sort Limit] [HAVING] Aggregate`` over an inner-join tree as one native call
        (``join_engine.fused_join_aggregate``); None when the plan has another shape or declines."""
        core, post_ops = self._extract_post_ops(plan)
        having = None
        if isinstance(core, Filter) and isinstance(core.input, Aggregate) and core.input.group_by:
            having, core = core.predicate, core.input
        if not isinstance(core, Aggregate):
            return None
        from . import join_engine
        try:
            return join_engine.fused_join_aggregate(self, core, having, post_ops)
        except Exception as exc:        # a plan is fully native or not at all: never fail the query
            return _native_exec.swallowed(exc, "fused join + aggregate")

    def _distinct_groupby(self, plan):
        """``DISTINCT k1..kn`` over ``[Project of plain columns] Filter*(Scan | inner-join tree)`` as the keyed
        group-by with a hidden ``MIN(row number)`` (F-033, design 3.4): one native call fused with the filter
        (or, over a star join, with the lookups: the fused v3 call, no user aggregate), the groups sorted by
        their first row (first appearance, as ``mx_distinct`` and the Python path give), then the post-ops
        above the DISTINCT. Only directly addressed key spaces (dictionary codes, small integer ranges); wide
        ones, plain strings, floats and nulls decline to ``mx_distinct`` / the old path. None: not that shape,
        or declined."""
        if _native_exec is None or not _native_exec.enabled() or _os.environ.get("MXFRAME_DISTINCT_GROUPBY", "1") in ("0", "false", "off"):
            return None                # (MXFRAME_DISTINCT_GROUPBY=0: mx_distinct as before, for A/B runs)
        core, post_ops = self._extract_post_ops(plan)
        if not post_ops or not isinstance(post_ops[0], Distinct):
            return None
        node, names = core, None
        if isinstance(core, Project):
            if not all(isinstance(e, Expr) and e.op == "col" and e._alias in (None, e.args[0]) for e in core.exprs):
                return None
            node, names = core.input, [e.args[0] for e in core.exprs]
        from .join_engine import plan_columns
        if names is None:
            names = plan_columns(node)
        keys = list(post_ops[0].subset or names or ())
        if not keys or len(set(keys)) != len(keys) or any(k not in names for k in keys):
            return None
        below = node
        while isinstance(below, Filter):
            below = below.input
        if not isinstance(below, (Scan, Join)):
            return None
        rest = post_ops[1:]
        first = Sort(None, [Expr("col", "__first")], [False])
        native_ops = [first] + ([rest[0]] if rest and isinstance(rest[0], Limit) else [])   # DISTINCT ... LIMIT: top-k groups
        agg = Aggregate(node, [Expr("col", k) for k in keys], [Expr("min", Expr("rowid")).alias("__first")])
        try:
            if isinstance(below, Scan):
                res = _native_exec.try_execute(self, agg, None, native_ops, distinct=True)
            else:
                from . import join_engine
                if isinstance(below, Join) and below.how != "inner":
                    return None
                res = join_engine.fused_join_aggregate(self, agg, None, native_ops, distinct=True)
                self._star_stash = None
        except Exception as exc:       # a plan is fully native or not at all: never fail the query
            res = _native_exec.swallowed(exc, "distinct as group-by")
        if res is None:
            return None
        res = res.select(keys)
        rest = rest[1:] if len(native_ops) == 2 else rest
        return self._apply_post_ops_custom(res, rest) if rest else res

    def _aggregate_consumers_first(self, plan):
        """``[Sort Limit] Project|Filter|Aggregate`` over an Aggregate: compute the part below as a table
        now (``_materialize_barrier``), keeping the sort / limit above it, ties broken by the group keys
        as before. Any other plan comes back as it was."""
        core, post_ops = self._extract_post_ops(plan)
        if not (isinstance(core, (Filter, Project, Aggregate)) and self._contains_aggregate(core.input)):
            return plan
        if isinstance(core, Filter) and isinstance(core.input, Aggregate) and core.input.group_by:
            return plan                                   # HAVING: the aggregate paths take it
        post_ops = self._key_tiebreak(core, post_ops)
        return self._rewrap(self._materialize_barrier(core), post_ops)

    @staticmethod
    def _rewrap(out, post_ops):
        """``out`` with the peeled-off Sort / Limit / Distinct / Tail nodes put back on top."""
        for op in post_ops:
            if isinstance(op, Sort):
                out = Sort(out, op.by, op.descending)
            elif isinstance(op, Limit):
                out = Limit(out, op.n, op.offset)
            elif isinstance(op, Distinct):
                out = Distinct(out, op.subset)
            else:
                out = Tail(out, op.n)
        return out

    def _computed_extremes(self, plan):
        """MIN / MAX of a computed value that is text, a date or timestamp, or a 64-bit integer (a CASE or COALESCE
        of such columns and literals, a date plus an interval, F-108): the aggregates evaluate their argument and cast it to float64, which
        cannot hold a string, a date, a ns timestamp or an integer past 2^53. Evaluate the argument once by Arrow
        into a column of the aggregate's input and aggregate that column, so the paths that already answer
        ``MIN(s)`` (F-072 ranks), ``MIN(date)`` (F-093) and ``MIN(int64)`` (F-090) take it. ``[Sort Limit] [HAVING]
        Aggregate`` is the shape taken; the rewritten plan is run (its integer MIN / MAX get their integer type
        back in ``compile_and_run``); None: not that shape."""
        core, post_ops = self._extract_post_ops(plan)
        having = core if isinstance(core, Filter) and isinstance(core.input, Aggregate) else None
        agg = core.input if having is not None else core
        if not isinstance(agg, Aggregate) or self._contains_aggregate(agg.input):
            return None
        wanted = [i for i, e in enumerate(agg.aggs)
                  if e.op in ("min", "max") and isinstance(e.args[0], Expr) and e.args[0].op not in ("col", "lit")]
        if not wanted:
            return None
        def kind(e, types):                         # what the value of e is made of: text / temporal / int, else None
            if e.op == "lit":
                v = e.args[0]
                return "text" if isinstance(v, str) else "temporal" if isinstance(v, (datetime.date, np.datetime64)) else None
            if e.op == "col":
                if e.args[0] not in types:
                    return None
                t = types[e.args[0]]
                t = t.value_type if pa.types.is_dictionary(t) else t
                return ("text" if pa.types.is_string(t) or pa.types.is_large_string(t)
                        else "temporal" if pa.types.is_date(t) or pa.types.is_timestamp(t)
                        else "int" if pa.types.is_integer(t) else None)
            if e.op == "add_us":                    # a DATE or timestamp plus an interval
                return "temporal"
            parts = (e.args[1:] if e.op == "case_when" else e.args if e.op in ("coalesce", "abs", "cast", "f32", "add", "sub", "mul", *_ARROW_ONLY_OPS)
                     else ())
            return next((k for k in (kind(a, types) for a in parts if isinstance(a, Expr)) if k), None)

        # Decide from the column types first (F-058): materializing a join below the aggregate to learn them cost a
        # whole join on every MIN / MAX of a float expression (random SF1 seed 1: 26 -> 48 ms), which this then left
        # alone. A column the types cannot name (computed below the aggregate) still needs the table.
        def cols(e):
            return ({e.args[0]} if e.op == "col" else set()).union(
                *[cols(a) for a in e.args if isinstance(a, Expr)])
        known = column_types(agg.input)
        unsure = [i for i in wanted if not cols(agg.aggs[i].args[0]) <= set(known)]
        wanted = [i for i in wanted if i in unsure or kind(agg.aggs[i].args[0], known)]
        if not wanted:
            return None
        node = agg.input
        while isinstance(node, Filter):
            node = node.input
        if isinstance(node, Scan):
            table, base = node.table, agg.input
        else:                                       # a join or a Project below: the columns as the aggregate sees them
            table = self._plan_to_table(self._materialize_joins(agg.input))
            base = Scan(table)
        real = {f.name: f.type for f in table.schema}
        wanted = [i for i in wanted if kind(agg.aggs[i].args[0], real)]
        if not wanted:
            return None
        taken = set(table.column_names)
        new_aggs = list(agg.aggs)
        for i in wanted:
            e = agg.aggs[i]
            n = f"__mm_{i}__"
            while n in taken:
                n += "_"
            taken.add(n)
            table = table.append_column(n, self._eval_expr_arrow(e.args[0], table))
            new_aggs[i] = Expr(e.op, Expr("col", n))
            new_aggs[i]._alias = e._alias
        def with_table(p):
            if isinstance(p, Scan):
                return Scan(table)
            return type(p)(with_table(p.input), *[getattr(p, f.name) for f in dataclasses.fields(p)[1:]])
        out = Aggregate(with_table(base), agg.group_by, new_aggs)
        if having is not None:
            out = Filter(out, having.predicate)
        return self.compile_and_run(self._rewrap(out, post_ops))

    def _string_minmax(self, plan):
        """MIN / MAX of a string column (F-072): the column's distinct values are ranked once in byte order
        (DuckDB's order), the aggregate runs on the integer ranks through every existing path (native
        executor, fused join, Arrow's null semantics) and the ranks are turned back into strings.
        ``[Sort Limit] [HAVING] Aggregate`` is the shape taken; the aggregate alone is computed and
        HAVING / Sort / Limit run above its string result. None: no string MIN / MAX in this plan."""
        core, post_ops = self._extract_post_ops(plan)
        having = core if isinstance(core, Filter) and isinstance(core.input, Aggregate) else None
        agg = core.input if having is not None else core
        if not isinstance(agg, Aggregate) or self._contains_aggregate(agg.input):
            return None
        wanted = {e.args[0].args[0] for e in agg.aggs if e.op in ("min", "max") and e.args[0].op == "col"}
        if not wanted:
            return None
        leaves, has_project = [], [False]

        def walk(p):
            if isinstance(p, Scan):
                leaves.append(p)
            elif isinstance(p, Join):
                walk(p.left), walk(p.right)
            else:
                has_project[0] |= isinstance(p, Project)
                walk(p.input)
        walk(agg.input)
        def is_str(t):
            t = t.value_type if pa.types.is_dictionary(t) else t
            return pa.types.is_string(t) or pa.types.is_large_string(t)
        any_string = any(is_str(f.type) for s in leaves for f in s.table.schema)
        schema = None
        strings = {}                                  # name -> the leaf Scans that hold it
        for c in wanted:
            held = [s for s in leaves if c in s.table.column_names]
            if held:
                is_s = is_str(held[0].table.schema.field(c).type)      # a bare name is the left-most copy (walk visits left first)
            else:                                     # a renamed copy (s_right), or a computed column
                from .io_parquet import _renamed_ref
                src = []                              # the copy a join renamed: x_right is the 2nd holder of x, x_rightN the Nth
                for n in dict.fromkeys(n for s in leaves for n in s.table.column_names):
                    if _renamed_ref(n, [c]):
                        k = int(c[len(n) + 6:] or 1)
                        copies = [s.table.schema.field(n).type for s in leaves if n in s.table.column_names]
                        if k < len(copies):
                            src = [copies[k]]
                            break
                if src:
                    is_s = is_str(src[0])
                elif not any_string:                  # no string column anywhere: nothing to rank
                    is_s = False
                else:                                 # a computed column: its type needs a zero-row run
                    from .lazy_frame import LazyFrame
                    schema = schema or LazyFrame(agg.input).schema
                    is_s = schema is not None and c in schema.names and is_str(schema.field(c).type)
            if is_s:
                strings[c] = held
        if not strings:
            return None

        base = agg.input
        if has_project[0] or any(len(h) != 1 for h in strings.values()):
            base = Scan(self._plan_to_table(self._materialize_joins(agg.input)))   # names as the aggregate sees them
            leaves = [base]
        ranked, back = {}, {}
        for c in strings:
            ranked[c], back[c] = _rank_strings(next(s for s in leaves if c in s.table.column_names).table.column(c))
        taken = {n for s in leaves for n in s.table.column_names}
        names = {}
        for c in strings:                             # a name no column holds, whatever the user called theirs
            n = f"__rank_{c}__"
            while n in taken:
                n += "_"
            taken.add(n)
            names[c] = n

        def add_ranks(p):
            if isinstance(p, Scan):
                t = p.table
                for c in strings:
                    if c in t.column_names:
                        t = t.append_column(names[c], ranked[c])
                return Scan(t)
            if isinstance(p, Join):
                return Join(add_ranks(p.left), add_ranks(p.right), p.left_on, p.right_on, p.how)
            return type(p)(add_ranks(p.input), *[getattr(p, f.name) for f in dataclasses.fields(p)[1:]])
        aggs, out_names = [], {}
        for i, e in enumerate(agg.aggs):
            name = e._alias or f"agg_{i}"
            if e.op in ("min", "max") and e.args[0].op == "col" and e.args[0].args[0] in strings:
                c = e.args[0].args[0]
                e = Expr(e.op, Expr("col", names[c])).alias(name)
                out_names[name] = c
            aggs.append(e)
        ranked_plan = Aggregate(add_ranks(base), agg.group_by, aggs)
        if self._session_device == "gpu" and any(len(v) > _GPU_EXACT_RANKS for v in back.values()):
            cpu = CustomOpsCompiler(device="cpu")             # float32 ranks would round: this aggregate stays on the CPU
            res = cpu.compile_and_run(ranked_plan)
            self.last_compile_provenance = cpu.last_compile_provenance
        else:
            res = self.compile_and_run(ranked_plan)
        for name, c in out_names.items():
            i = res.schema.get_field_index(name)
            res = res.set_column(i, name, pc.take(back[c], pc.cast(res.column(i), pa.int64())))
        if having is not None:
            res = pc.filter(res, pc.fill_null(self._eval_predicate(having.predicate, res), _npscalar(False, type=pa.bool_())))
        return self._compile_and_run(self._rewrap(Scan(res), post_ops)) if post_ops else res

    def _materialize_barrier(self, plan):
        """Compute what sits below an aggregate result as a table, so the operator above works on it.

        The engine runs one Aggregate over a scan (plus a HAVING filter and Sort/Limit on top).
        Anything else that consumes an aggregate's output - a Project (``with_columns`` / ``select``
        after ``agg``), a Filter that is not the aggregate's HAVING, another Aggregate (a groupby on
        an aggregate column, or a global aggregate over groups) - is run on ``Scan(result)`` of the
        subtree below it, computed by a recursive ``compile_and_run``.  ``plan`` has its Sort/Limit/
        Distinct/Tail post-ops already peeled off."""
        if isinstance(plan, Filter) and isinstance(plan.input, Aggregate) and plan.input.group_by:
            # HAVING on a grouped aggregate: the filter stays (the global-aggregate paths do not
            # apply one); the aggregate below it may itself sit on an aggregate
            return Filter(self._materialize_barrier(plan.input), plan.predicate)
        if isinstance(plan, Aggregate) and not self._contains_aggregate(plan.input):
            # The aggregate paths read `Aggregate(Filter*(Scan))` (a Project directly below is
            # inlined into it). Any other input - a Filter above a Project, a Project above a
            # Filter under another Project - is computed as a table first.
            inner = self._inline_project_into_aggregate(plan).input if plan.group_by else plan.input
            node = inner
            while isinstance(node, Filter):
                node = node.input
            if not isinstance(node, Scan):
                return Aggregate(Scan(self._plan_to_table(plan.input)), plan.group_by, plan.aggs)
            return plan
        if isinstance(plan, (Filter, Project, Aggregate)) and self._contains_aggregate(plan.input):
            below = Scan(self.compile_and_run(plan.input))
            if isinstance(plan, Filter):
                return Filter(below, plan.predicate)
            if isinstance(plan, Project):
                return Project(below, plan.exprs)
            return Aggregate(below, plan.group_by, plan.aggs)
        return plan

    @staticmethod
    def _arrow_aggregate_reason(plan, preds, table, late=False):
        """``(why, exact_sum)``: why Arrow's hash aggregate answers ``Aggregate(Filter*(Scan))`` instead of the
        fused / native paths ("" when they do). A null in a column the plan reads, or (``late``: every pipeline
        declined) an integer SUM or arithmetic the compiled graph and the global shortcuts cannot add in int64.
        ``exact_sum``: integers are computed in int64 (F-037, F-060) instead of float64."""
        read = set()
        for e in list(plan.group_by) + list(plan.aggs) + list(preds):
            _expr_col_names(e, read, tests_ok=not late)     # (late: every pipeline declined; the Arrow path keeps nulls)
        has_nulls = any(n in table.column_names and table.column(n).null_count for n in read) \
            or _can_be_null([*plan.group_by, *plan.aggs, *preds])
        arrow_ops = any(isinstance(e, Expr) and e.uses(*SQL_MATH) for e in [*plan.group_by, *plan.aggs, *preds])
        if any(e.op not in ("sum", "min", "max", "mean", "count") for e in plan.aggs):
            return "", False
        from .pipeline_program import has_int_sum, int_sum_inexact
        # An integer SUM is int64 on every path (F-060): the native executor and the fused pipeline add it in
        # int64 themselves; a plan that gets here after they declined is added by Arrow's checked sum, never by
        # a float64 path. With nulls in the plan Arrow answers anyway, and its sums of integers are int64 too.
        exact_sum = late and (has_int_sum(list(plan.aggs), table) or int_sum_inexact(list(plan.aggs), table, preds))
        wide_minmax = any(e.op in ("min", "max") and e.args[0].op == "col" and e.args[0].args[0] in table.column_names
                          and pa.types.is_integer(table.column(e.args[0].args[0]).type)
                          and table.column(e.args[0].args[0]).type.bit_width >= 64 for e in plan.aggs)
        temporal = any(_temporal_extreme(e, table) for e in plan.aggs)     # F-093: float64 cannot hold a date / ns timestamp
        if wide_minmax and (has_nulls or temporal):
            exact_sum = True        # Arrow answers: it takes a 64-bit integer extreme in integers, whatever the values (F-090)
        elif wide_minmax and late and not exact_sum:
            # F-090: every kernel that computes in float64 rounds the MIN / MAX of an integer past 2^53. The executor
            # and the fused pipelines take it in int64 (F-060c), so this is asked only once all of them have declined
            # (it used to be a pass over the column for every min / max query, before any kernel ran)
            for e in plan.aggs:
                if e.op in ("min", "max") and e.args[0].op == "col" and e.args[0].args[0] in table.column_names:
                    c = table.column(e.args[0].args[0])
                    if pa.types.is_integer(c.type) and c.type.bit_width >= 64 and len(c):
                        mm = pc.min_max(c)
                        lo, hi = mm["min"].as_py(), mm["max"].as_py()
                        if lo is not None and max(abs(lo), abs(hi)) > 2 ** 53:
                            exact_sum = True
                            break
        if temporal:
            return "a min / max of a date or timestamp keeps its type (Arrow)", exact_sum
        why = "a column the plan reads has nulls" if has_nulls else (
            "an expression only Arrow evaluates (//, power, sqrt, ln: exact in double, errors only for the rows kept)"
            if arrow_ops else
            "an integer sum or arithmetic the pipelines declined, or a min / max past 2^53 (computed exactly in int64)"
            if exact_sum else "")
        return why, exact_sum

    def _aggregate_with_nulls(self, plan, having_pred, post_ops, optimizer_trace, t0, late=False):
        """``Aggregate(Filter*(Scan))`` over columns that contain nulls, by Arrow's hash
        aggregate; None when the plan has no null in a column it reads (or is another shape).
        ``late``: called after every pipeline declined, where the next stop is the compiled graph:
        integer arithmetic that could pass 2^53 goes to Arrow's checked kernels instead (F-061)."""
        plan = self._inline_project_into_aggregate(plan)
        if not isinstance(plan, Aggregate):
            return None
        preds, node = [], plan.input
        while isinstance(node, Filter):
            preds.append(node.predicate)
            node = node.input
        if not isinstance(node, Scan):
            return None
        table = node.table
        why, exact_sum = self._arrow_aggregate_reason(plan, preds, table, late)
        if not why:
            return None

        from .pipeline_program import _int_valued
        t_start = t0 if t0 is not None else _time.perf_counter()
        prev = getattr(_PRECISE, "on", False)
        _PRECISE.on = True                      # float64 arithmetic, like the CPU kernels
        try:
            if any(p.uses("sqrt", "ln") for p in preds):      # one filter at a time: a sqrt / ln sees only the kept rows
                for pred in _raising_last(preds):
                    table = pc.filter(table, pc.fill_null(self._eval_predicate(pred, table), _npscalar(False, type=pa.bool_())))
            elif preds:
                mask = None
                for pred in preds:
                    m = pc.fill_null(self._eval_predicate(pred, table), _npscalar(False, type=pa.bool_()))   # null is not true
                    mask = m if mask is None else pc.and_(mask, m)
                table = pc.filter(table, mask)
            key_arrays, key_names = [], []
            for i, e in enumerate(plan.group_by):
                name = e._alias or (e.args[0] if e.op == "col" else f"__gk_{i}__")
                arr = table.column(e.args[0]) if e.op == "col" else self._eval_group_key(e, table)
                key_arrays.append(_decode_dict(arr))
                key_names.append(name)
            agg_names, agg_arrays = [], []
            for i, e in enumerate(plan.aggs):
                agg_names.append(e._alias or f"agg_{i}")
                if e.op == "count" and e.args[0].op == "lit":
                    agg_arrays.append(_npa(np.zeros(table.num_rows, dtype=np.int8)))   # count(*)
                    continue
                arr = None
                if _temporal_extreme(e, table):
                    agg_arrays.append(_decode_dict(table.column(e.args[0].args[0])))      # F-093: stays a date / timestamp
                    continue
                if e.op == "sum" or (e.op == "mean" and _int_valued(e.args[0], table)) \
                        or (exact_sum and e.op in ("min", "max")):
                    _PRECISE.on = False                 # integers stay int64 (a sum of integers is int64 on every path, F-060)
                    try:
                        arr = self._eval_expr_arrow(e.args[0], table)
                    finally:
                        _PRECISE.on = True
                    if not pa.types.is_integer(arr.type):
                        arr = None
                agg_arrays.append(arr if arr is not None else self._eval_expr_arrow(e.args[0], table))
        finally:
            _PRECISE.on = prev

        if key_names:
            src = pa.Table.from_arrays(key_arrays + agg_arrays,
                                       names=key_names + [f"__v{i}__" for i in range(len(agg_arrays))])
            spec = [(f"__v{i}__", {"sum": "sum", "min": "min", "max": "max", "mean": "mean",
                                  "count": "count"}[e.op]) for i, e in enumerate(plan.aggs)]
            grouped = _group_aggregate(src, key_names, spec)      # Table.group_by imports pandas
            out_cols = [grouped.column(n) for n in key_names]
            for i, e in enumerate(plan.aggs):
                c = grouped.column(f"__v{i}___{spec[i][1]}")
                exact = (e.op == "sum" or exact_sum and e.op in ("min", "max")) and pa.types.is_integer(agg_arrays[i].type)
                if _temporal_extreme(e, table):
                    out_cols.append(c)                                         # F-093: the column's own date / timestamp type
                elif exact and e.op in ("min", "max"):
                    out_cols.append(pc.cast(c, agg_arrays[i].type))        # the column's own integer type
                else:
                    out_cols.append(pc.cast(c, pa.int64()) if e.op == "count" or exact else pc.cast(c, pa.float64()))
            result = pa.Table.from_arrays(out_cols, names=key_names + agg_names)
        else:
            cols = []
            for e, arr in zip(plan.aggs, agg_arrays):
                if e.op == "count":
                    cols.append(_npa([pc.count(arr).as_py()], type=pa.int64()))
                    continue
                if _temporal_extreme(e, table):
                    cols.append(_temporal_scalar(pc.min_max(arr)[e.op], arr.type))
                    continue
                exact = (e.op == "sum" or exact_sum and e.op in ("min", "max")) and pa.types.is_integer(arr.type)
                if exact and e.op == "sum":
                    cols.append(_npa([_int_sum(arr)], type=pa.int64()))        # OverflowError past int64
                    continue
                if exact:
                    cols.append(_npa([pc.min_max(arr)[e.op].as_py()], type=arr.type))      # the column's own integer type
                    continue
                if e.op in ("min", "max"):
                    cols.append(_npa([float_extreme(arr, e.op)], type=pa.float64()))
                    continue
                if e.op == "mean" and pa.types.is_integer(arr.type):       # F-060 / F-126: added exactly (wider than int64), divided once
                    cols.append(_npa([_int_mean(arr)], type=pa.float64()))
                    continue
                v = {"sum": pc.sum, "mean": pc.mean}[e.op](arr)
                cols.append(_npa([v.as_py()], type=pa.float64()))
            result = pa.Table.from_arrays(cols, names=agg_names)

        if having_pred is not None:
            result = result.filter(pc.fill_null(self._eval_predicate(having_pred, result), _npscalar(False, type=pa.bool_())))
        if post_ops:
            result = self._apply_post_ops_custom(result, post_ops)
        self.last_compile_provenance = {
            "device": self._session_device, "rows": int(result.num_rows),
            "grouped": bool(key_names), "n_groups": int(result.num_rows) if key_names else 0,
            "cache_hit": False, "compile_ms": 0.0,
            "execute_ms": round((_time.perf_counter() - t_start) * 1000, 1),
            "gpu_input_path": "pyarrow",
            "optimizer_trace": list(optimizer_trace or []),
            "path": "arrow_null_semantics",
        }
        return result

    @staticmethod
    def _empty_grouped_result(agg_node, group_keys, unique_key_cols):
        """Grouped aggregate over zero selected rows: no groups, right column names/types."""
        agg_names = [e._alias or f"agg_{i}" for i, e in enumerate(agg_node.aggs)]
        keys = [unique_key_cols[k].slice(0, 0) for k in group_keys]
        aggs = [_npa([], type=pa.int64() if e.op == "count" else pa.float64())
                for e in agg_node.aggs]
        return pa.Table.from_arrays(keys + aggs, names=list(group_keys) + agg_names)

    _WINDOW_OPS = frozenset({"window", "row_number", "rank", "dense_rank"})

    @classmethod
    def _inline_project_into_aggregate(cls, plan):
        """Inline every Project directly under a grouped Aggregate (chained ``with_columns``)."""
        while True:
            new = cls._inline_one_project(plan)
            if new is plan:
                return plan
            plan = new

    @classmethod
    def _inline_one_project(cls, plan):
        """``Aggregate(Project(x))`` -> ``Aggregate(x)`` with the projected expressions
        substituted into the group keys / aggregate arguments.

        The AOT aggregation kernels evaluate their arguments from the source columns, so a
        ``with_columns(...)`` computed column feeding a grouped aggregate (TPC-H Q8) would
        otherwise push the query onto the MAX Graph JIT path.  Left alone when the
        Project holds window functions."""
        if not (isinstance(plan, Aggregate) and plan.group_by and isinstance(plan.input, Project)):
            return plan
        proj = plan.input

        def has_window(e):
            if not isinstance(e, Expr):
                return False
            return e.op in cls._WINDOW_OPS or any(has_window(a) for a in e.args)

        if any(has_window(e) for e in proj.exprs):
            return plan
        mapping = {}
        for e in proj.exprs:
            name = e._alias or (e.args[0] if e.op == "col" else None)
            if name is None or (e.op == "col" and e.args[0] == name):
                continue                      # pass-through column: the source table has it
            mapping[name] = e

        import copy

        def subst(e, top=False):
            if not isinstance(e, Expr):
                if isinstance(e, list):
                    return [subst(a) for a in e]
                return e
            if e.op == "col" and e.args[0] in mapping:
                new = copy.copy(mapping[e.args[0]])       # refers to source columns only
                new._alias = e.args[0] if top else None
                return new
            new = copy.copy(e)
            new.args = tuple(subst(a) for a in e.args)
            return new

        return Aggregate(proj.input, [subst(e, top=True) for e in plan.group_by],
                         [subst(e) for e in plan.aggs])

    @classmethod
    def _collect_predicates(cls, plan):
        """Collect all Filter predicates from the plan tree."""
        preds = []
        def _walk(p):
            if isinstance(p, Filter):
                preds.append(p.predicate)
                _walk(p.input)
            elif isinstance(p, Join):
                raise RuntimeError("_collect_predicates: Join should have been materialized")
            elif isinstance(p, (Sort, Limit, Distinct, Tail)):
                _walk(p.input)
            elif hasattr(p, 'input'):
                _walk(p.input)
        _walk(plan)
        return preds

    @classmethod
    def _strip_filter_nodes(cls, plan):
        """Remove Filter nodes from the plan tree without applying them."""
        if isinstance(plan, Scan): return plan
        if isinstance(plan, Join):
            raise RuntimeError("_strip_filter_nodes: Join should have been materialized")
        if isinstance(plan, Filter):
            return cls._strip_filter_nodes(plan.input)
        if isinstance(plan, Project):
            return Project(cls._strip_filter_nodes(plan.input), plan.exprs)
        if isinstance(plan, Aggregate):
            return Aggregate(cls._strip_filter_nodes(plan.input), plan.group_by, plan.aggs)
        if isinstance(plan, Sort):
            return Sort(cls._strip_filter_nodes(plan.input), plan.by, plan.descending)
        if isinstance(plan, Limit):
            return Limit(cls._strip_filter_nodes(plan.input), plan.n, plan.offset)
        if isinstance(plan, Distinct):
            return Distinct(cls._strip_filter_nodes(plan.input), plan.subset)
        if isinstance(plan, Tail):
            return Tail(cls._strip_filter_nodes(plan.input), plan.n)
        if hasattr(plan, 'input'):
            plan.input = cls._strip_filter_nodes(plan.input)
        return plan

    def compile_and_run(self, plan, verbose=False, optimizer_trace=None) -> pa.Table:
        """Run ``plan``; the result of ``count`` aggregates is always exact int64."""
        # F-083: a column-only Project above Sort / Limit just drops the sort keys the SELECT list
        # leaves out. Run the Sort / Limit as post-ops (the top-n paths need them at the top), then pick.
        keep = None
        if isinstance(plan, Project) and isinstance(plan.input, (Sort, Limit)) \
                and all(e.op == "col" for e in plan.exprs):
            keep, plan = plan.exprs, plan.input
        # F-087: the paths below take "the first n rows". An OFFSET window is run as the first
        # offset + n rows (the top-n paths see Sort + Limit as before) and the offset rows are cut off.
        skip = 0
        if isinstance(plan, Limit) and (plan.offset or plan.n is None):
            skip = plan.offset                               # (no limit: only the rows are skipped; the sum is kept in int64)
            plan = plan.input if plan.n is None else Limit(plan.input, min(plan.n + plan.offset, _MAX_ROWS))
        plan = self._resolve_inner_offsets(plan)
        result = self._compile_and_run(plan, verbose=verbose, optimizer_trace=optimizer_trace)
        result = self._exact_counts(plan, result)
        if skip:
            result = result.slice(min(skip, result.num_rows))
        if keep is not None:
            result = result.select([e.args[0] for e in keep]).rename_columns([e._alias or e.args[0] for e in keep])
        return result

    def _resolve_inner_offsets(self, plan):
        """A Sort / Limit / Distinct / Tail chain with a Limit-with-OFFSET below its top node: that window
        decides which rows the nodes above it see, so it is computed first and replaced by its table."""
        chain = []
        while isinstance(plan, (Sort, Limit, Distinct, Tail)):
            chain.append(plan)
            plan = plan.input
        for i in range(len(chain) - 1, -1, -1):          # innermost first
            if isinstance(chain[i], Limit) and chain[i].offset and i:
                plan = Scan(self.compile_and_run(Limit(plan, chain[i].n, chain[i].offset)))
            else:
                plan = self._rewrap(plan, [chain[i]])
        return plan

    @classmethod
    def _exact_counts(cls, plan, result: pa.Table) -> pa.Table:
        """Cast the columns of ``count`` aggregates to int64 (the older float kernels still return a rounded double),
        and of integer MIN / MAX to the column's own integer type: the bytecode kernels return those as int64 since
        F-060c (exact at any size), narrowed here to int32 / int16 / uint8 ...; the older float kernels' doubles are
        cast too, and a fraction raises."""
        node = plan
        while isinstance(node, (Filter, Sort, Limit, Distinct, Tail)):
            node = node.input
        # A Project above the aggregate has already recomputed its columns (its input's counts
        # were made exact when that input ran): the names it outputs are not the aggregate's.
        agg = node if isinstance(node, Aggregate) else None
        if agg is None:
            return result
        int_cols = None
        for i, e in enumerate(agg.aggs):
            minmax = e.op in ("min", "max") and e.args and getattr(e.args[0], "op", None) == "col"
            if e.op != "count" and not minmax:
                continue
            name = e._alias or f"agg_{i}"
            idx = result.schema.get_field_index(name)
            if idx < 0:
                continue
            ftype = result.schema.field(idx).type
            col = result.column(idx)
            if e.op == "count":
                if not pa.types.is_integer(ftype):
                    result = result.set_column(idx, name, pc.cast(pc.round(col), pa.int64()))
                continue
            # F-090: MIN / MAX of an integer column is that integer type (DuckDB), not the kernels' float; the
            # kernels' int64 extreme (F-060c) takes the column's own width (int32, uint8 ...) here
            if int_cols is None:
                int_cols = {n: t for n, t in column_types(agg.input).items() if pa.types.is_integer(t)}
            want = int_cols.get(e.args[0].args[0])
            if want is not None and ftype != want and (pa.types.is_floating(ftype) or pa.types.is_integer(ftype)):
                result = result.set_column(idx, name, pc.cast(col, want))   # safe cast: a fraction raises
        return result

    def _compile_and_run(self, plan, verbose=False, optimizer_trace=None) -> pa.Table:
        """Optimized execution with three-tier caching + post-ops.

        Pipeline:
        -1. Materialize any Join nodes (recursive, bottom-up).
        0. Extract post-ops (Sort/Limit/Distinct) from top of plan.
        1. Check input-prep cache; on hit skip to step 5.
        2. Pre-encode group keys on original table (cached).
        3. Compute filter mask as numpy boolean array.
        4. Apply mask via numpy boolean indexing; store in prep cache.
        5. Look up / compile cached MAX Graph model.
        6. Execute model and assemble output.
        7. Apply post-ops via Mojo kernels.
        """
        t0 = _time.perf_counter()
        self._resolve_auto(plan)

        # Record whether the plan has Join nodes BEFORE materialising them.
        # Used below to emit an accurate 'join_mojo_shortcut' provenance label
        # for plans whose only heavy work is a Mojo-executed hash join.
        _had_join = self._has_join_node(plan)

        # -1a0 -- F-033: SELECT DISTINCT as the keyed group-by with a hidden MIN(row number), one native call
        _distinct = self._distinct_groupby(plan)
        if _distinct is not None:
            return _distinct

        # -1a- -- F-068: arithmetic / CASE / HAVING over an aggregate's output (a Project, Filter or second
        # Aggregate above it) runs on the small result table: the aggregate below goes through every
        # native path first (fused join, star, single table) instead of the whole plan being declined
        plan = self._aggregate_consumers_first(plan)

        # -1a1 -- F-108: MIN / MAX of a computed string / date / timestamp / 64-bit integer becomes a column
        _cmm = self._computed_extremes(plan)
        if _cmm is not None:
            return _cmm

        # -1a1 -- F-072: MIN / MAX of a string column, computed on the byte-order ranks of its values
        _strmm = self._string_minmax(plan)
        if _strmm is not None:
            return _strmm

        # -1a -- F-046a slice 3: an aggregate over inner joins runs as one native call, no joined rows
        if _had_join and _native_exec is not None:
            _fused = self._fused_join_aggregate(plan)
            if _fused is not None:
                return _fused

        # -1a2 -- F-080: COUNT(right col) per left key over a LEFT JOIN, with no joined rows (TPC-H Q13)
        if _had_join and _native_exec is not None:
            _core, _post = self._extract_post_ops(plan)
            if isinstance(_core, Aggregate) and isinstance(_core.input, Join) and _core.input.how == "left":
                from . import join_engine
                try:
                    _counts = join_engine.left_join_counts(self, _core, _post)
                except Exception as exc:        # a plan is fully native or not at all: never fail the query
                    _counts = _native_exec.swallowed(exc, "left join counts")
                if _counts is not None:
                    self.last_compile_provenance = {
                        "device": "cpu", "rows": int(_counts.num_rows), "grouped": True, "n_groups": int(_counts.num_rows),
                        "cache_hit": None, "compile_ms": 0.0, "gpu_input_path": "numpy", "path": "join_mojo_shortcut"}
                    return _counts

        # -1 -- Materialize Join nodes (bottom-up) --------------------
        plan = self._materialize_joins(plan)
        self._star_stash = None            # (a declined fused attempt's partners: used by now, or never)
        # -1b -- A Sort/Limit/Distinct/Tail below a Filter/Project/Aggregate changes which rows
        # the operators above see: run it now (the Filter/Aggregate paths below only look at the
        # Scan under them, so a Limit there used to be ignored).
        plan = self._lower_row_ops(plan)

        # 0 -- Extract post-ops (Sort/Limit/Distinct) -----------------
        plan, post_ops = self._extract_post_ops(plan)
        # 0-a -- ORDER BY above Projects or Filters over a group-by: the barrier below turns the aggregate into
        # a table, so the group keys must join the sort columns now (the native path gets them too)
        if isinstance(plan, (Project, Filter)):
            post_ops = self._key_tiebreak(plan, post_ops)
        # 0-b -- Operators above an aggregate result run on the materialized aggregate
        plan = self._materialize_barrier(plan)

        # 0a -- Extract HAVING filter: a Filter wrapping an Aggregate is HAVING,
        # not a pre-scan WHERE.  Pull it out and apply after aggregation.
        having_pred = None
        if isinstance(plan, Filter):
            inner_no_filt = self._strip_filter_nodes(plan.input)
            if self._find_aggregate(inner_no_filt) is not None:
                having_pred = plan.predicate
                plan = plan.input

        # 0a1 -- ORDER BY ties: group keys are the last sort columns on every path below. The native
        # executor adds them itself, so it gets the post-ops as written.
        _native_post_ops = post_ops
        post_ops = self._key_tiebreak(plan, post_ops)

        # 0a2 -- SQL null semantics.  The kernels have no notion of null (a null group key was
        # dropped, a null value turned a sum into NaN), so an aggregate that touches a column
        # with nulls is computed by Arrow's hash aggregate: a null key is its own group, sum /
        # mean / min / max / count skip null values, a comparison with null is not true.
        _null_result = self._aggregate_with_nulls(plan, having_pred, post_ops, optimizer_trace, t0)
        if _null_result is not None:
            return _null_result

        # 0b -- No-compute shortcut: when plan has no Aggregate/Project,
        # process in PyArrow (preserving all column types including strings).
        plan_no_filters = self._strip_filter_nodes(plan)
        if self._find_aggregate(plan_no_filters) is None:
            # No Aggregate: use PyArrow path (handles strings, year, Project, Filter)
            deferred = self._deferred_dicts(plan)
            result = self._filter_topk(plan, post_ops)       # WHERE ... ORDER BY ... LIMIT k first
            if result is not None:
                post_ops = post_ops[2:]                      # the Sort and the Limit are done
            else:
                result, post_ops = self._single_table(plan, post_ops, deferred)
            if result is None:
                if deferred:                                 # the old way: decoded before the filter
                    plan = self._decode_scan_dicts(plan, deferred)
                    deferred = ()
                result = self._plan_to_table(plan)
            if deferred and result is not None:
                result = _decode_deferred_cols(result, deferred)
            if post_ops:
                result = self._apply_post_ops_custom(result, post_ops)
            t1 = _time.perf_counter()
            # Accurate provenance: if the plan contained a join (materialised by
            # Mojo kernels above), label it 'join_mojo_shortcut' rather than the
            # misleading 'pyarrow_shortcut'.  Column gathering is still Arrow, but
            # the O(n) join-index computation ran in Mojo.
            _shortcut_path = "join_mojo_shortcut" if _had_join else "pyarrow_shortcut"
            self.last_compile_provenance = {
                "device": self._session_device,
                "rows": int(result.num_rows),
                "grouped": False,
                "n_groups": 0,
                "cache_hit": None,
                "compile_ms": 0.0,
                "execute_ms": round((t1 - t0) * 1000, 1),
                "gpu_input_path": "pyarrow",
                "optimizer_trace": list(optimizer_trace or []),
                "path": _shortcut_path,
            }
            if verbose:
                print(f"[omxcore] PyArrow shortcut — {(t1-t0)*1000:.1f}ms")
            return result

        # F-008 -- fused pipeline: filter + arithmetic + aggregates in one vectorized AOT pass
        # (CPU or GPU), for grouped and global aggregate plans. None -> use the paths below.
        # A Project under a grouped aggregate (a select / with_columns after distinct, say) is folded
        # into the aggregate first: the fused kernels accumulate float64 in float64, while the GPU
        # path it used to fall back to rounds float64 columns to float32 (F-016 fuzz seed 5061).
        plan = self._inline_project_into_aggregate(plan)
        # F-030 / F-031 -- native executor: the whole plan in one Mojo call
        if _native_exec is not None:          # (declines at once when MXFRAME_NATIVE=0)
            try:
                _native = _native_exec.try_execute(self, plan, having_pred, _native_post_ops)
            except Exception as _exc:      # a plan is fully native or not at all: never fail the query
                _native = _native_exec.swallowed(_exc, "executor")
            if _native is not None:
                return _native
        if try_fused_aggregate is not None:
            _fused = try_fused_aggregate(self, plan, having_pred, post_ops, optimizer_trace, t0)
            if _fused is not None:
                return _fused
        # A plan the GPU session's own pipeline declined is answered on the CPU: by the executor
        # first, so CPU and GPU sessions give the same digits (F-022 / F-031)
        if _native_exec is not None and _native_exec.enabled() and self._session_device == "gpu":
            try:
                _native = _native_exec.try_execute(self, plan, having_pred, _native_post_ops, gpu_fallback=True)
            except Exception as _exc:
                _native = _native_exec.swallowed(_exc, "executor")
            if _native is not None:
                return _native

        # F-061 -- the compiled graph and the global shortcuts below compute integers in int64 or
        # float64 without an overflow check: arithmetic that could pass 2^53 runs in Arrow (checked)
        _exact_result = self._aggregate_with_nulls(plan, having_pred, post_ops, optimizer_trace, t0, late=True)
        if _exact_result is not None:
            return _exact_result

        # 1b2 -- Global aggregate shortcut: bypass MAX Engine for un-grouped aggs.
        # For large tables with a filter, try the fused masked-kernel path first
        # (no table.filter() allocation). Fall back to PyArrow for unsupported ops.
        _agg_check = self._find_aggregate(self._strip_filter_nodes(plan))
        if _agg_check is not None and not _agg_check.group_by:
            # ── Fast path: masked_global_sum Mojo kernel ──────────────────────
            _masked_result = self._compute_masked_global_agg(plan, _agg_check)
            if _masked_result is not None:
                if post_ops:
                    _masked_result = self._apply_post_ops_custom(_masked_result, post_ops)
                t1 = _time.perf_counter()
                self.last_compile_provenance = {
                    "device": self._session_device, "rows": 1,
                    "grouped": False, "n_groups": 0, "cache_hit": False,
                    "compile_ms": 0.0,
                    "execute_ms": round((t1 - t0) * 1000, 1),
                    "gpu_input_path": "masked_mojo",
                    "optimizer_trace": list(optimizer_trace or []),
                    "path": "masked_global_agg_mojo",
                }
                return _masked_result
            # ── Fallback: PyArrow path (min/max/complex predicates) ───────────
            _agg_orig  = self._find_aggregate(plan)
            _inner_tbl = self._plan_to_table(_agg_orig.input)
            result     = self._compute_global_agg_pyarrow(_inner_tbl, _agg_orig)
            if post_ops:
                result = self._apply_post_ops_custom(result, post_ops)
            t1 = _time.perf_counter()
            self.last_compile_provenance = {
                "device": self._session_device, "rows": 1,
                "grouped": False, "n_groups": 0, "cache_hit": False,
                "compile_ms": 0.0,
                "execute_ms": round((t1 - t0) * 1000, 1),
                "gpu_input_path": "pyarrow",
                "optimizer_trace": list(optimizer_trace or []),
                "path": "global_agg_pyarrow",
            }
            return result

        # 1 -- Resolve plan, predicates, and decide execution path -----
        plan = self._inline_project_into_aggregate(plan)
        original_scan = self._find_scan(plan)
        plan_clean = self._strip_filter_nodes(plan)
        predicates = self._collect_predicates(plan)

        # 1b -- Rewrite case_when/isin/startswith as derived col refs (before prep_key).
        plan_clean, derived_specs = self._extract_derived_cols(plan_clean)

        # GPU filter path: when on GPU and ALL predicates are numeric comparisons,
        # skip per-column CPU boolean-indexing. Upload full (unfiltered) arrays once
        # and cache them; pass a small int32 mask per query. The compiled MAX Graph
        # is reused across all filter values on the same table.
        on_gpu = (self._session_device == "gpu") or (
            self._device_arg == "auto" and self._has_gpu
            and original_scan.table.num_rows > AUTO_GPU_THRESHOLD
        )
        use_gpu_filter = (
            on_gpu
            and bool(predicates)
            and all(self._can_compile_predicate_gpu(p) for p in predicates)
        )

        # pred_sig is empty for GPU filter path: graph is reused across filter values.
        pred_sig = () if use_gpu_filter else tuple(p.signature() for p in predicates)
        _watch_table(original_scan.table)
        prep_key = (id(original_scan.table), original_scan.table.num_rows,
                    plan_clean.signature(), pred_sig, self._session_device)

        # 2 -- Check input-prep cache (fastest main path) --------------
        cached_prep = _INPUT_PREP_CACHE.get(prep_key)
        if cached_prep is not None:
            col_names = cached_prep['col_names']
            col_arrays = cached_prep['col_arrays']
            extra_inputs = cached_prep['extra_inputs']
            n_groups = cached_prep['n_groups']
            unique_key_cols = cached_prep['unique_key_cols']
            group_keys = cached_prep['group_keys']
            N = cached_prep['N']
            _group_ids_full = cached_prep.get('_group_ids_full')
            self._N = N
            self._maybe_switch_device(N)
        else:
            # 3 -- Pre-encode group keys on ORIGINAL table (cached) ----
            agg_node = self._find_aggregate(plan_clean)
            group_keys = []
            n_groups = 0
            unique_key_cols = {}
            group_ids_full = None
            _group_ids_full = None

            if agg_node is not None and agg_node.group_by:
                # Resolve group keys: plain col("name") → string; Expr (e.g. year()) → pre-eval.
                # For Expr keys, evaluate them via thin PyArrow (integer SIMD ops like date//10000)
                # and inject as synthetic columns into the scan table.  The actual groupby
                # aggregation (group_sum / group_count kernels) still runs entirely in Mojo.
                group_keys = []
                _gk_table = original_scan.table
                _gk_out = {}          # internal key column -> output name (alias that shadows a source column)
                for _e in agg_node.group_by:
                    if _e.op == "col" and _e._alias in (None, _e.args[0]):
                        group_keys.append(_e.args[0])
                    else:
                        # Derived key (e.g. year(col("l_shipdate")).alias("l_year"))
                        _col_name = _e._alias or f"__gk_{len(group_keys)}__"
                        if _col_name in _gk_table.column_names:
                            # The alias shadows a source column (with_columns(k+10).alias("k")):
                            # the key is the computed values, kept under an internal name so the
                            # source column stays untouched for the aggregate arguments.
                            _internal = f"__gk_{len(group_keys)}_{_col_name}__"
                            _gk_out[_internal] = _col_name
                            _col_name = _internal
                        if _col_name not in _gk_table.column_names:
                            # a renamed column (select(col("s").alias("b"))) is the source column
                            _arr = (_gk_table.column(_e.args[0]) if _e.op == "col"
                                    else self._eval_group_key(_e, _gk_table))
                            _gk_table = _gk_table.append_column(_col_name, _arr)
                        group_keys.append(_col_name)
                if _gk_table is not original_scan.table:
                    original_scan = Scan(_gk_table)
                group_ids_full, n_groups, unique_key_cols = self._build_group_ids_cached(
                    original_scan.table, group_keys, gpu_compiler=self
                )
                if _gk_out:
                    unique_key_cols = {_gk_out.get(k, k): v for k, v in unique_key_cols.items()}
                    group_keys = [_gk_out.get(k, k) for k in group_keys]

            if use_gpu_filter:
                # 4a -- GPU filter path: full arrays, no per-column CPU copy ----
                # Columns are uploaded once and cached on GPU. Only the int32 mask
                # (computed from the predicate) changes per query.
                N = original_scan.table.num_rows
                self._N = N
                self._maybe_switch_device(N)
                extra_inputs = {}
                if group_ids_full is not None:
                    extra_inputs["__group_ids__"] = group_ids_full
                col_names = []
                col_arrays = {}
                for name in original_scan.table.column_names:
                    if not self._is_numeric_arrow_type(
                        original_scan.table.schema.field(name).type
                    ):
                        continue
                    np_arr, _, _ = self._column_to_numpy_cached(original_scan.table.column(name))
                    if np_arr is None:
                        continue
                    col_names.append(name)
                    col_arrays[name] = np_arr
                # 4a-derived: pre-compute case_when/isin/startswith (unmasked on GPU)
                for deriv_name, deriv_expr in derived_specs:
                    arr = self._eval_expr_arrow(deriv_expr, original_scan.table)
                    col_arrays[deriv_name] = _np_of(arr, zero_copy_only=False).astype(np.float64)
                    col_names.append(deriv_name)
                _group_ids_full = group_ids_full
                _INPUT_PREP_CACHE[prep_key] = {
                    'col_names': col_names, 'col_arrays': col_arrays,
                    'extra_inputs': extra_inputs, 'n_groups': n_groups,
                    'unique_key_cols': unique_key_cols, 'group_keys': group_keys,
                    'N': N, '_group_ids_full': group_ids_full,
                }
            else:
                # 4b -- Standard CPU filter path -----------------------
                mask_np = None
                if predicates:
                    combined = None
                    for pred in predicates:
                        m = self._eval_predicate(pred, original_scan.table)
                        combined = m if combined is None else pc.and_(combined, m)
                    mask_np = _np_of(combined, zero_copy_only=False)

                N = int(mask_np.sum()) if mask_np is not None else original_scan.table.num_rows
                self._N = N
                self._maybe_switch_device(N)

                extra_inputs = {}
                if group_ids_full is not None:
                    gids = group_ids_full[mask_np] if mask_np is not None else group_ids_full
                    if mask_np is not None:
                        groups_present = np.zeros(n_groups, dtype=bool)
                        groups_present[gids] = True
                        if not groups_present.all():
                            present_idx = np.where(groups_present)[0]
                            remap = np.empty(n_groups, dtype=np.int32)
                            remap[present_idx] = np.arange(len(present_idx), dtype=np.int32)
                            gids = remap[gids]
                            n_groups = len(present_idx)
                            unique_key_cols = {
                                k: pc.take(v, _npa(present_idx.astype(np.int64)))
                                for k, v in unique_key_cols.items()
                            }
                    extra_inputs["__group_ids__"] = gids

                col_names = []
                col_arrays = {}
                for name in original_scan.table.column_names:
                    if not self._is_numeric_arrow_type(
                        original_scan.table.schema.field(name).type
                    ):
                        continue
                    np_arr, _, _ = self._column_to_numpy_cached(original_scan.table.column(name))
                    if np_arr is None:
                        continue
                    if mask_np is not None:
                        np_arr = np_arr[mask_np]
                    col_names.append(name)
                    col_arrays[name] = np_arr

                # 4b-derived: pre-compute case_when/isin/startswith, then apply mask
                for deriv_name, deriv_expr in derived_specs:
                    arr = self._eval_expr_arrow(deriv_expr, original_scan.table)
                    np_arr = _np_of(arr, zero_copy_only=False).astype(np.float64)
                    if mask_np is not None:
                        np_arr = np_arr[mask_np]
                    col_arrays[deriv_name] = np_arr
                    col_names.append(deriv_name)

                _INPUT_PREP_CACHE[prep_key] = {
                    'col_names': col_names, 'col_arrays': col_arrays,
                    'extra_inputs': extra_inputs, 'n_groups': n_groups,
                    'unique_key_cols': unique_key_cols, 'group_keys': group_keys,
                    'N': N,
                }

        # GPU filter path: compute fresh int32 mask per query (query-specific, not cached).
        # The mask is small relative to column data; stable columns are reused from cache.
        mask_np_int32 = None
        if use_gpu_filter and predicates:
            combined_pred = predicates[0]
            for p in predicates[1:]:
                combined_pred = Expr("and", combined_pred, p)
            arrow_mask = self._eval_predicate(combined_pred, original_scan.table)
            mask_np_int32 = _np_of(arrow_mask, zero_copy_only=False).astype(np.int32)

        all_names = col_names + list(extra_inputs.keys())
        all_arrays = {**col_arrays, **extra_inputs}
        if mask_np_int32 is not None:
            all_names = all_names + ["__filter_mask__"]
            all_arrays["__filter_mask__"] = mask_np_int32

        # 4.5 -- CPU AOT fast path: bypass MAX Graph for grouped CPU aggs ──────
        if (self._session_device == "cpu" and self._aot is not None
                and group_keys and not use_gpu_filter):
            _aot_result = self._execute_cpu_aot(
                plan_clean, col_arrays, extra_inputs, n_groups,
                group_keys, unique_key_cols,
            )
            if _aot_result is not None:
                if having_pred is not None:
                    _aot_result = pc.filter(_aot_result,
                        self._eval_predicate(having_pred, _aot_result)
                    )
                if post_ops:
                    _aot_result = self._apply_post_ops_custom(_aot_result, post_ops)
                t1 = _time.perf_counter()
                self.last_compile_provenance = {
                    "device": self._session_device,
                    "rows": int(_aot_result.num_rows),
                    "grouped": True,
                    "n_groups": int(n_groups),
                    "cache_hit": True,
                    "compile_ms": 0.0,
                    "execute_ms": round((t1 - t0) * 1000, 1),
                    "gpu_input_path": "aot_ctypes",
                    "optimizer_trace": list(optimizer_trace or []),
                    "path": "cpu_aot",
                }
                if verbose:
                    print(f"[omxcore] CPU AOT — {(t1-t0)*1000:.1f}ms")
                return _aot_result


        # 4.55 -- Empty input on the GPU device: nothing to upload (cuMemAlloc(0) fails and the
        # MAX Graph fallback would JIT for it); the CPU kernels return the empty result.
        # Also when the (GPU-path) filter mask selects no row: N is then the full row count.
        _selects_nothing = mask_np_int32 is not None and not mask_np_int32.any()
        if (self._session_device == "gpu" and (N == 0 or _selects_nothing) and self._aot is not None
                and group_keys):
            if _selects_nothing:
                _aot_result = self._empty_grouped_result(
                    self._find_aggregate(plan_clean), group_keys, unique_key_cols)
            else:
                _aot_result = self._execute_cpu_aot(
                    plan_clean, col_arrays, extra_inputs, n_groups,
                    group_keys, unique_key_cols,
                    mask_np_int32=None,
                )
            if _aot_result is not None:
                if having_pred is not None:
                    _aot_result = pc.filter(_aot_result,
                        self._eval_predicate(having_pred, _aot_result)
                    )
                if post_ops:
                    _aot_result = self._apply_post_ops_custom(_aot_result, post_ops)
                self.last_compile_provenance = {
                    "device": self._session_device, "rows": int(_aot_result.num_rows),
                    "grouped": True, "n_groups": int(n_groups), "cache_hit": True,
                    "compile_ms": 0.0,
                    "execute_ms": round((_time.perf_counter() - t0) * 1000, 1),
                    "gpu_input_path": "aot_ctypes",
                    "optimizer_trace": list(optimizer_trace or []),
                    "path": "cpu_aot",
                }
                return _aot_result

        # 4.6 -- grouped aggregate the fused pipeline declined, GPU session: the CPU kernels
        # (float64 accumulation) run it, so the device never changes the digits (F-022). The
        # float32 GPU group kernels rounded float64 inputs and sums. When filtered,
        # mask_np_int32 turns filtered-out rows into gid=-1, which the kernels skip.
        if (self._session_device == "gpu" and self._aot is not None
                and group_keys):
            _aot_result = self._execute_cpu_aot(
                plan_clean, col_arrays, extra_inputs, n_groups,
                group_keys, unique_key_cols,
                mask_np_int32=mask_np_int32,
            )
            if _aot_result is not None:
                if having_pred is not None:
                    _aot_result = pc.filter(_aot_result,
                        self._eval_predicate(having_pred, _aot_result)
                    )
                if post_ops:
                    _aot_result = self._apply_post_ops_custom(_aot_result, post_ops)
                t1 = _time.perf_counter()
                self.last_compile_provenance = {
                    "device": "cpu",              # CPU work in a GPU session
                    "rows": int(_aot_result.num_rows),
                    "grouped": True,
                    "n_groups": int(n_groups),
                    "cache_hit": True,
                    "compile_ms": 0.0,
                    "execute_ms": round((t1 - t0) * 1000, 1),
                    "optimizer_trace": list(optimizer_trace or []),
                    "path": "cpu_aot",
                    "gpu_declined": True,
                }
                if verbose:
                    print(f"[omxcore] CPU AOT (GPU session) — {(t1-t0)*1000:.1f}ms")
                return _aot_result

        # 5 -- Graph cache lookup --------------------------------------
        cache_key = self._compute_cache_key(
            plan_clean,
            all_names,
            all_arrays,
            n_groups,
            optimizer_trace=optimizer_trace,
        )
        cache_hit = cache_key in _MODEL_CACHE

        if cache_hit:
            model, agg_names = _MODEL_CACHE[cache_key]
            t_compile = _time.perf_counter()
        else:
            if verbose:
                print("[omxcore] Compiling query plan...", end=" ", flush=True)

            input_types = [
                TensorType(_max_dtype(all_arrays[n]), list(all_arrays[n].shape), self._device_ref)
                for n in all_names
            ]

            graph = Graph(
                name="mxframe_custom",
                input_types=input_types,
                custom_extensions=[Path(self.kernels_path)],
            )
            with graph:
                nodes = {n: graph.inputs[i] for i, n in enumerate(all_names)}
                result_nodes = self._visit_plan_custom(plan_clean, nodes, n_groups=n_groups)
                graph.output(*result_nodes.values())

            model = self._session.load(graph)
            agg_names = list(result_nodes.keys())
            _MODEL_CACHE[cache_key] = (model, agg_names)
            t_compile = _time.perf_counter()

        # 6 -- Execute (with GPU buffer cache) ------------------------
        # Stable inputs (everything except __filter_mask__) are cached as
        # driver.Buffer objects so repeated queries on the same data skip
        # the PCIe upload entirely. __filter_mask__ is query-specific and
        # always re-uploaded (it is small: N * 4 bytes).
        gpu_input_path = "cpu_numpy"
        if self._session_device == "gpu":
            stable_names = [n for n in all_names if n != "__filter_mask__"]
            cached_bufs = _GPU_BUFFER_CACHE.get(prep_key)
            execute_inputs = []
            if cached_bufs is not None and all(n in cached_bufs for n in stable_names):
                for n in all_names:
                    if n == "__filter_mask__":
                        mask_buf, _ = self._to_gpu_input(all_arrays[n])
                        execute_inputs.append(mask_buf)
                    else:
                        execute_inputs.append(cached_bufs[n])
                gpu_input_path = "gpu_cached"
            else:
                new_bufs: Dict[str, Any] = {}
                for n in all_names:
                    gpu_buf, path_used = self._to_gpu_input(all_arrays[n])
                    execute_inputs.append(gpu_buf)
                    if n != "__filter_mask__":
                        new_bufs[n] = gpu_buf
                _GPU_BUFFER_CACHE[prep_key] = new_bufs
                gpu_input_path = "uploaded"
        else:
            execute_inputs = [all_arrays[n] for n in all_names]

        output_vals = model.execute(*execute_inputs)
        t_exec = _time.perf_counter()

        if verbose:
            compile_ms = (t_compile - t0) * 1000
            exec_ms = (t_exec - t_compile) * 1000
            total_ms = (t_exec - t0) * 1000
            if cache_hit:
                print(f"[omxcore] Cache hit. Executed on {self._session_device.upper()} in "
                      f"{total_ms:.1f}ms (data prep: {compile_ms:.1f}ms, execute: {exec_ms:.1f}ms)")
            else:
                print(f"done in {total_ms:.1f}ms "
                      f"(compile: {compile_ms:.1f}ms, execute: {exec_ms:.1f}ms). "
                      f"Next run with same schema: ~{exec_ms:.0f}ms")

        self.last_compile_provenance = {
            "device": self._session_device,
            "rows": int(N),
            "grouped": bool(group_keys),
            "n_groups": int(n_groups),
            "cache_hit": cache_hit,
            "compile_ms": round((t_compile - t0) * 1000, 1),
            "execute_ms": round((t_exec - t_compile) * 1000, 1),
            "gpu_input_path": gpu_input_path,
            "optimizer_trace": list(optimizer_trace or []),
            "path": "compiled",
            "gpu_filter": use_gpu_filter,
        }

        # 7 -- Assemble output ----------------------------------------
        agg_arrays = [_npa(np.asarray(_np_of(t)).reshape(-1)) for t in output_vals]

        if unique_key_cols:
            if (use_gpu_filter and group_keys
                    and mask_np_int32 is not None and _group_ids_full is not None):
                # Groups whose rows were all masked out produce silent zeros in the
                # kernel output. Remove them so they don't appear in the result.
                surviving = np.zeros(n_groups, dtype=bool)
                surviving[_group_ids_full[mask_np_int32.astype(bool)]] = True
                if not surviving.all():
                    surv_filter = _npa(surviving)
                    unique_key_cols = {k: pc.filter(v, surv_filter) for k, v in unique_key_cols.items()}
                    agg_arrays = [pc.filter(arr, surv_filter) for arr in agg_arrays]
            key_arrays = [unique_key_cols[k] for k in group_keys]
            result = pa.Table.from_arrays(key_arrays + agg_arrays, names=group_keys + agg_names)
        else:
            result = pa.Table.from_arrays(agg_arrays, names=agg_names)

        # 8 -- Apply HAVING filter (post-aggregation predicate) -------
        if having_pred is not None:
            having_mask = self._eval_predicate(having_pred, result)
            result = pc.filter(result, having_mask)

        # 9 -- Apply post-ops (Sort/Limit/Distinct via Mojo kernels) ---
        if post_ops:
            result = self._apply_post_ops_custom(result, post_ops)

        return result

    # ── CPU AOT grouped aggregation ───────────────────────────────────────────

    def _execute_cpu_aot(
        self, plan_clean, col_arrays, extra_inputs, n_groups,
        group_keys, unique_key_cols,
        _aot_override=None,
        mask_np_int32=None,
    ) -> "Optional[pa.Table]":
        """Execute a grouped aggregation via AOT ctypes, bypassing MAX Graph entirely.

        Called only for CPU sessions when self._aot is not None and plan has group_by.
        Returns pa.Table on success, None to fall back to MAX Graph.
        """
        _aot = _aot_override if _aot_override is not None else self._aot
        is_cpu = _aot_override is None      # CPU kernels: float64 accumulation, wider inputs
        agg_node = self._find_aggregate(plan_clean)
        if agg_node is None or not agg_node.group_by:
            return None

        gids = extra_inputs.get("__group_ids__")
        if gids is None:
            return None
        if not gids.flags["C_CONTIGUOUS"] or gids.dtype != np.int32:
            gids = np.ascontiguousarray(gids, dtype=np.int32)

        # GPU filter path: apply predicate mask as gid=-1 sentinel so GPU kernels
        # skip filtered-out rows (kernels check `if gid >= 0 and gid < ng`).
        # Compact the group space so output only contains groups with actual data.
        if mask_np_int32 is not None:
            effective_gids = np.where(mask_np_int32 == 1, gids, np.int32(-1))
            has_data = np.zeros(n_groups, dtype=bool)
            _valid = effective_gids[effective_gids >= 0]
            if len(_valid) == 0:
                return None  # all rows filtered out
            has_data[_valid] = True
            present_idx = np.where(has_data)[0].astype(np.int32)
            remap = np.empty(n_groups, dtype=np.int32)
            remap[present_idx] = np.arange(len(present_idx), dtype=np.int32)
            compact_gids = effective_gids.copy()
            _pos = compact_gids >= 0
            compact_gids[_pos] = remap[compact_gids[_pos]]
            gids = compact_gids
            n_groups = len(present_idx)
            unique_key_cols = {
                k: pc.take(v, _npa(present_idx.astype(np.int64)))
                for k, v in unique_key_cols.items()
            }

        # Build a mini PyArrow table so _eval_expr_arrow can evaluate expressions
        # like col_a * (1 - col_b) on the already-filtered column arrays.
        # Note: col_arrays contains only numeric source columns and pre-computed
        # derived columns (e.g. __cw_0__, __cw_1__ from case_when substitution).
        # Engine slots (__group_ids__, __filter_mask__) live in extra_inputs, not
        # col_arrays, so no exclusion filter is needed here.
        # Perf: skip string/object dtype columns — they are group keys, not agg
        # values; converting numpy object arrays (800K strings) to pa.array is O(N)
        # slow and would dominate hot-call time.
        mini_cols = {}
        for k, v in col_arrays.items():
            if v.dtype.kind in ("f", "i", "u"):   # float, int, uint only
                mini_cols[k] = _npa(v)
            else:
                # String/object columns: preserve as-is via zero-copy pa.array
                # (stays as dictionary/string type, no Python iteration needed)
                try:
                    mini_cols[k] = _npa(v, from_pandas=True)
                except Exception:
                    pass  # skip columns that can't be converted
        mini_table = pa.table(mini_cols) if mini_cols else None

        agg_names: list = []
        agg_arrays: list = []
        for i, expr in enumerate(agg_node.aggs):
            name = expr._alias or f"agg_{i}"
            try:
                if expr.op == "count":
                    # exact int64 on both devices: the GPU count kernel accumulates float32
                    # (saturates at 2**24 per group), so the host counts the labels itself
                    if is_cpu:
                        res = _aot.group_count(gids, n_groups)
                    else:
                        res = np.bincount(gids[gids >= 0], minlength=n_groups)
                    agg_names.append(name)
                    agg_arrays.append(_npa(np.rint(res).astype(np.int64)))
                    continue

                if expr.op not in ("sum", "min", "max", "mean"):
                    return None  # unsupported op → fall back to MAX Graph

                if mini_table is None:
                    return None
                if is_cpu:
                    if self._is_simple_col(expr.args[0]) is not None:
                        # plain column: float32 stays float32 (zero-copy), kernels widen
                        vals = _np_of(self._eval_expr_arrow(expr.args[0], mini_table), 
                            zero_copy_only=False)
                        if vals.dtype != np.float32:
                            vals = vals.astype(np.float64, copy=False)
                        vals = np.ascontiguousarray(vals)
                    else:
                        vals = self._eval_expr_f64(expr.args[0], mini_table)
                    kern = {"sum": _aot.group_sum, "min": _aot.group_min,
                            "max": _aot.group_max, "mean": _aot.group_mean}[expr.op]
                    res = kern(vals, gids, n_groups)
                else:
                    val_pa  = self._eval_expr_arrow(expr.args[0], mini_table)
                    vals_f32 = _np_of(val_pa, zero_copy_only=False).astype(np.float32)
                    if not vals_f32.flags["C_CONTIGUOUS"]:
                        vals_f32 = np.ascontiguousarray(vals_f32)
                    if expr.op == "sum":
                        res = _aot.group_sum_f32(vals_f32, gids, n_groups)
                    elif expr.op == "min":
                        res = _aot.group_min_f32(vals_f32, gids, n_groups)
                    elif expr.op == "max":
                        res = _aot.group_max_f32(vals_f32, gids, n_groups)
                    else:  # mean
                        res = _aot.group_mean_f32(vals_f32, gids, n_groups)

                if expr.op in ("min", "max"):
                    res = self._fix_infinite_extremes(res, vals if is_cpu else vals_f32, gids,
                                                      n_groups, expr.op)
                agg_names.append(name)
                agg_arrays.append(_npa(res.astype(np.float64)))

            except Exception:
                return None  # any error → fall back to MAX Graph

        if not agg_names:
            return None

        key_arrays = [unique_key_cols[k] for k in group_keys]
        return pa.Table.from_arrays(key_arrays + agg_arrays, names=group_keys + agg_names)

    @staticmethod
    def _fix_infinite_extremes(res, vals, gids, n_groups, op):
        """min / max of a group whose only values are +inf / -inf is that infinity.

        The kernels start each group at the largest finite float (their identity), which an
        infinity never beats, so such a group came back as +/-3.4e38 (or 1.8e308)."""
        inf_val = np.inf if op == "min" else -np.inf
        is_inf = vals == inf_val
        if not is_inf.any():
            return res
        valid = gids >= 0
        only_inf = (np.bincount(gids[valid & ~is_inf], minlength=n_groups) == 0) & \
                   (np.bincount(gids[valid & is_inf], minlength=n_groups) > 0)
        res = np.array(res, dtype=np.float64, copy=True)
        res[only_inf] = inf_val
        return res

    def _visit_plan_custom(self, plan, nodes, *, n_groups=0):
        if isinstance(plan, Scan):
            return nodes
        elif isinstance(plan, Project):
            upstream = self._visit_plan_custom(plan.input, nodes, n_groups=n_groups)
            out = {}
            # Pass through internal engine slots (e.g. __group_ids__) so that
            # an Aggregate above a with_columns Project can still find them.
            for _k, _v in upstream.items():
                if _k.startswith("__") and _k.endswith("__"):
                    out[_k] = _v
            for i, expr in enumerate(plan.exprs):
                name = expr._alias or f'col_{i}'
                out[name] = self._visit_expr(expr, upstream)
            return out
        elif isinstance(plan, Filter):
            raise RuntimeError(
                'Filter node reached _visit_plan_custom -- '
                '_strip_filters should have removed all Filter nodes.'
            )
        elif isinstance(plan, (Sort, Limit, Distinct, Tail)):
            # Post-ops: should have been extracted by _extract_post_ops.
            # If they reach here, just recurse through to inner plan.
            return self._visit_plan_custom(plan.input, nodes, n_groups=n_groups)
        elif isinstance(plan, Aggregate):
            return self._visit_aggregate_custom(plan, nodes, n_groups=n_groups)
        raise NotImplementedError(f'Unsupported plan node: {type(plan)}')

    def _visit_aggregate_custom(self, plan, nodes, *, n_groups):
        upstream = self._visit_plan_custom(plan.input, nodes, n_groups=n_groups)
        out = {}
        grouped = bool(plan.group_by)
        on_gpu = (self._session_device == "gpu")

        for i, expr in enumerate(plan.aggs):
            name = expr._alias or f'agg_{i}'
            if grouped and n_groups > 0:
                gid_raw = ops.cast(upstream["__group_ids__"], DType.int32)

                if "__filter_mask__" in upstream:
                    # GPU filter path: encode filtered-out rows as gid = -1.
                    # Existing kernels already check `gid >= 0`, so they naturally
                    # skip rows where the predicate is false — no kernel changes needed.
                    # Formula: effective_gid = (gid + 1) * mask - 1
                    #   mask=1 → (gid+1)*1 - 1 = gid  (process)
                    #   mask=0 → (gid+1)*0 - 1 = -1   (skip)
                    mask_i32 = ops.cast(upstream["__filter_mask__"], DType.int32)
                    one = ops.constant(1, dtype=DType.int32, device=self._device_ref)
                    gid_node = ops.sub(
                        ops.mul(ops.add(gid_raw, one), mask_i32),
                        one,
                    )
                else:
                    gid_node = gid_raw

                # Both GPU and CPU kernels write final aggregated results directly
                # to an output tensor of shape [n_groups] using atomic adds.
                # On GPU: shared-mem privatization up to MAX_GROUPS (8192), then
                # global-atomic fallback — no cardinality ceiling.
                out_type = TensorType(DType.float32, [n_groups], self._device_ref)

                if on_gpu and n_groups <= 0:
                    raise ValueError(
                        f"Grouped GPU path requires n_groups > 0; got {n_groups}."
                    )

                if expr.op == "count":
                    out[name] = ops.custom(
                        name="group_count",
                        values=[gid_node],
                        out_types=[out_type],
                        device=self._device_ref,
                    )[0]
                elif expr.op in ("sum", "min", "max", "mean"):
                    val_node = ops.cast(self._visit_expr(expr.args[0], upstream), DType.float32)
                    if expr.op == "mean":
                        sum_node = ops.custom(
                            name="group_sum",
                            values=[val_node, gid_node],
                            out_types=[out_type],
                            device=self._device_ref,
                        )[0]
                        cnt_node = ops.custom(
                            name="group_count",
                            values=[gid_node],
                            out_types=[out_type],
                            device=self._device_ref,
                        )[0]
                        out[name] = ops.div(sum_node, ops.cast(cnt_node, DType.float32))
                    else:
                        out[name] = ops.custom(
                            name=f"group_{expr.op}",
                            values=[val_node, gid_node],
                            out_types=[out_type],
                            device=self._device_ref,
                        )[0]
                else:
                    raise NotImplementedError(
                        f"Grouped '{expr.op}' is not yet supported. "
                        f"Add a group_{expr.op}.mojo kernel and wire it."
                    )
            else:
                out[name] = self._visit_expr(expr, upstream)
        return out

    @staticmethod
    def _find_aggregate(plan):
        if isinstance(plan, Aggregate): return plan
        if hasattr(plan, 'input'): return CustomOpsCompiler._find_aggregate(plan.input)
        return None

    @staticmethod
    def _has_join_node(plan) -> bool:
        """Return True if the plan tree contains any Join node (before materialisation)."""
        if isinstance(plan, Join):
            return True
        if isinstance(plan, (Filter, Project, Aggregate, Sort, Limit, Distinct, Tail)):
            return CustomOpsCompiler._has_join_node(plan.input)
        return False

    # -- Sort / Limit / Distinct via Mojo kernels ----------------------

    def _encode_sort_key(self, table: pa.Table, by_exprs, descending: list) -> np.ndarray:
        """Encode sort key columns into a single int32 composite key.

        Phase 3: vectorised rank mapping replaces the Python for-loop in the
        original dictionary-encode path — 10-20x faster at large N.

        Uses PyArrow dictionary_encode (O(N) hash-based unique finding) then
        a vectorised numpy rank assignment O(n_unique).  Much faster than
        np.unique which does a full O(N log N) sort.
        """
        key_names = [e.args[0] for e in by_exprs]

        per_col_ranks = []   # (rank_arr int32, n_unique int)
        for k in key_names:
            arr = table.column(k)
            if isinstance(arr, pa.ChunkedArray):
                arr = _combine(arr)
            arr = _canonical_floats(arr)          # -0.0 = 0.0 and one NaN, as in SQL (F-077)
            # PyArrow dictionary_encode: O(N) hash → encounter-order indices
            enc = pc.dictionary_encode(arr)
            dict_arr = enc.dictionary
            # Vectorised rank: sort_indices gives sorted_order[rank] = orig_dict_idx
            # Invert with rank_of[orig_dict_idx] = rank  (single numpy scatter)
            sorted_order = _np_of(pc.sort_indices(dict_arr), zero_copy_only=False)
            rank_of = np.empty(len(dict_arr), dtype=np.int32)
            rank_of[sorted_order] = np.arange(len(sorted_order), dtype=np.int32)
            n_dict = len(dict_arr)
            if enc.indices.null_count:
                # nulls sort after every value, in either direction (DuckDB's default): they
                # get one extra rank past the real ones, which a descending flip leaves alone
                is_null = _np_of(pc.is_null(enc.indices), zero_copy_only=False)
                raw_idx = _np_of(pc.fill_null(enc.indices, _npscalar(0, type=enc.indices.type)), zero_copy_only=False).astype(np.int32)
                ranks = rank_of[raw_idx] if n_dict else np.zeros(len(raw_idx), dtype=np.int32)
                ranks = np.where(is_null, np.int32(n_dict), ranks).astype(np.int32)
                per_col_ranks.append((ranks, n_dict + 1, n_dict))
            else:
                raw_idx = _np_of(enc.indices, zero_copy_only=False).astype(np.int32)
                per_col_ranks.append((rank_of[raw_idx], n_dict, n_dict))

        # Fold the per-column ranks (most significant first) into one int32 key.
        # The mixed-radix value idx0*n1*n2 + idx1*n2 + idx2 can exceed int32 when the
        # columns have many distinct values, so accumulate in int64 and, whenever the
        # next column could overflow, renumber the running key by its dense rank
        # (np.unique) which preserves order and is always < len(table).
        composite = np.zeros(len(table), dtype=np.int64)
        radix = 1                                   # exclusive upper bound of `composite`
        for i, (idx, n_unique, n_real) in enumerate(per_col_ranks):
            if descending[i]:
                flipped = np.int32(n_real - 1) - idx
                idx = np.where(idx < n_real, flipped, idx) if n_real != n_unique else flipped
            if radix * n_unique >= 2**31:
                composite = np.unique(composite, return_inverse=True)[1].astype(np.int64)
                radix = int(composite.max()) + 1 if len(composite) else 1
            composite = composite * n_unique + idx
            radix *= n_unique
        if radix >= 2**31:
            composite = np.unique(composite, return_inverse=True)[1]
        return composite.astype(np.int32)

    def _apply_sort_custom(self, table: pa.Table, sort_node: Sort, topk: int = None) -> pa.Table:
        """Sort an Arrow table by integer composite key.

        CPU: pure numpy argsort -- no MAX Graph overhead.
        GPU (Phase 5): AOT bitonic sort kernel (sort_topk_i32_gpu) + AOT gather.
          Falls back to MAX Graph sort_indices kernel when _aot_gpu is None.

        topk: if set, only return the first topk sorted rows (ORDER BY ... LIMIT topk).
        """
        if (topk is not None and topk < table.num_rows and self._session_device != "gpu"
                and topk <= 65536 and topk * 8 <= table.num_rows      # heaps pay off for small k only
                and all(isinstance(e, Expr) and e.op == "col" for e in sort_node.by)):
            # ORDER BY plain numeric columns LIMIT k: per-worker heaps in one native pass (F-044)
            from . import native_exec
            desc = list(sort_node.descending) if isinstance(sort_node.descending, (list, tuple)) \
                else [bool(sort_node.descending)] * len(sort_node.by)
            idx = native_exec.try_topk(table, [e.args[0] for e in sort_node.by], desc, topk)
            if idx is not None:
                got = native_exec.try_gather(self, table, idx)
                return got if got is not None else pc.take(table, _npa(idx))
        composite_key = self._encode_sort_key(table, sort_node.by, sort_node.descending)
        N = len(composite_key)
        k = topk if topk is not None and topk < N else N

        if self._session_device != "gpu" or N == 0 or k == 0 or self._aot_gpu is None:
            # CPU fast path: numpy argsort, no graph compilation (also for empty tables and LIMIT 0, where
            # there is nothing to upload or allocate (cuMemAlloc(0) fails), and when the GPU AOT library is unavailable)
            if k < N:
                # Partial sort: np.argpartition + sort of k elements
                part_idx = np.argpartition(composite_key, k)[:k]
                sorted_indices = part_idx[np.argsort(composite_key[part_idx], kind='stable')]
            elif self._aot is not None and N >= RADIX_SORT_MIN_ROWS and N < 2**31 \
                    and composite_key.dtype in (np.int32, np.int64, np.float32, np.float64):
                # Parallel stable LSD radix sort (F-012): ~15x np.argsort at 10M rows.
                # Verified in O(n) before use: one unexplained order failure was seen once in a
                # loaded full-suite run (not reproducible in 5,600 stress runs), so a bad result
                # falls back to np.argsort instead of returning a wrong order.
                sorted_indices = self._aot.sort_indices(composite_key)
                if not _is_sorted_permutation(composite_key, sorted_indices):
                    _warn_radix_fallback()
                    sorted_indices = np.argsort(composite_key, kind='stable')
            else:
                sorted_indices = np.argsort(composite_key, kind='stable')
            return pc.take(table, _npa(sorted_indices.astype(np.int64)))

        # ── GPU path ────────────────────────────────────────────────────────
        # Phase 5: prefer AOT GPU sort (no JIT, cached key array, AOT gather)
        if self._aot_gpu is not None:
            def cpu_sort():
                idx = np.argsort(composite_key, kind="stable")[:k]
                return pc.take(table, _npa(idx.astype(np.int64)))

            def gpu_sort():
                sorted_indices = self._aot_gpu.sort_topk(
                    composite_key, k=k,
                    descending=False,  # _encode_sort_key already flips keys for descending
                )
                if _is_sorted_topk(composite_key, sorted_indices, k):
                    return self._aot_gpu.gather_table(table, sorted_indices)
                # F-055: a kernel that ran out of GPU memory only prints an `oom log` and returns a wrong
                # order (seen when another process held the GPU's memory): redo the sort on the CPU.
                _sort_check.gpu_sort_fallbacks += 1
                _warn_radix_fallback("the GPU sort returned a wrong order (out of GPU memory?)")
                return cpu_sort()
            # F-056: over the GPU's free memory, or out of it: the stable CPU argsort gives the same order
            return gpu_budget.run_piece(
                "sort", gpu_budget.sort_bytes(N, composite_key.itemsize) + gpu_budget.gather_bytes(table, k),
                gpu_sort, cpu_sort, shape=(N, k, composite_key.dtype.str, str(table.schema.types)))

        # Fallback: MAX Graph bitonic sort + numpy gather
        cache_key = ("sort_indices", N, self._session_device)
        model = _POST_OP_MODEL_CACHE.get(cache_key)
        if model is None:
            key_type = TensorType(DType.int32, [N], self._device_ref)
            flag_type = TensorType(DType.int32, [1], self._device_ref)
            graph = Graph(
                name="mxframe_sort",
                input_types=[key_type, flag_type],
                custom_extensions=[Path(self.kernels_path)],
            )
            with graph:
                indices = ops.custom(
                    name="sort_indices",
                    values=[graph.inputs[0], graph.inputs[1]],
                    out_types=[TensorType(DType.int32, [N], self._device_ref)],
                    device=self._device_ref,
                )[0]
                graph.output(indices)
            model = self._session.load(graph)
            _POST_OP_MODEL_CACHE[cache_key] = model
        desc_flag = np.array([0], dtype=np.int32)
        k_buf = driver.Buffer.from_numpy(composite_key).to(self._gpu_driver)
        f_buf = driver.Buffer.from_numpy(desc_flag).to(self._gpu_driver)
        (out_idx,) = model.execute(k_buf, f_buf)
        # Download indices and gather on CPU (original MAX Graph gather was broken)
        idx_np = np.asarray(_np_of(out_idx)).reshape(-1).astype(np.int32)
        return pc.take(table, _npa(idx_np.astype(np.int64)))

    def _gpu_gather_table(self, table: pa.Table, idx_tensor, N: int) -> pa.Table:
        """Gather rows of `table` using an index tensor already on GPU.

        For float32 and int32 columns the gather runs on GPU via the
        `gather_f32` / `gather_i32` Mojo kernels.  All other column types
        (strings, dates, booleans, etc.) fall back to a single CPU Arrow.take
        after reading the index tensor once.

        `idx_tensor` is the raw MAX output tensor (still on GPU).
        `N` is the number of rows in `table` (= len(idx_tensor)).
        """
        # Compile / cache a single-column gather model for this N
        def _get_gather_model(dtype_key: str, mojo_name: str, arr_dtype: DType):
            ck = (mojo_name, N, self._session_device)
            m = _POST_OP_MODEL_CACHE.get(ck)
            if m is None:
                val_type = TensorType(arr_dtype, [N], self._device_ref)
                idx_type = TensorType(DType.int32, [N], self._device_ref)
                g = Graph(
                    name=f"mxframe_{mojo_name}",
                    input_types=[val_type, idx_type],
                    custom_extensions=[Path(self.kernels_path)],
                )
                with g:
                    out = ops.custom(
                        name=mojo_name,
                        values=[g.inputs[0], g.inputs[1]],
                        out_types=[TensorType(arr_dtype, [N], self._device_ref)],
                        device=self._device_ref,
                    )[0]
                    g.output(out)
                m = self._session.load(g)
                _POST_OP_MODEL_CACHE[ck] = m
            return m

        # Upload index once and reuse the buffer across all columns
        idx_np = np.asarray(_np_of(idx_tensor)).reshape(-1).astype(np.int32)
        idx_buf = driver.Buffer.from_numpy(idx_np).to(self._gpu_driver)

        gathered_arrays = []
        gathered_names = []
        cpu_fallback_needed = False
        cpu_fallback_indices = idx_np  # read back only if needed

        for col_name in table.column_names:
            col = table.column(col_name)
            if isinstance(col, pa.ChunkedArray):
                col = _combine(col)

            if pa.types.is_float32(col.type):
                np_col = _np_of(col, zero_copy_only=False).astype(np.float32)
                model = _get_gather_model("f32", "gather_f32", DType.float32)
                col_buf = driver.Buffer.from_numpy(np_col).to(self._gpu_driver)
                (out_t,) = model.execute(col_buf, idx_buf)
                gathered_arrays.append(_npa(np.asarray(_np_of(out_t)).reshape(-1)))
            elif pa.types.is_integer(col.type):
                np_col = _np_of(col, zero_copy_only=False).astype(np.int32)
                model = _get_gather_model("i32", "gather_i32", DType.int32)
                col_buf = driver.Buffer.from_numpy(np_col).to(self._gpu_driver)
                (out_t,) = model.execute(col_buf, idx_buf)
                gathered_arrays.append(_npa(np.asarray(_np_of(out_t)).reshape(-1)))
            else:
                # Non-numeric column: fall back to Arrow.take (index already on CPU)
                gathered_arrays.append(pc.take(col, _npa(idx_np.astype(np.int64))))
            gathered_names.append(col_name)

        return pa.Table.from_arrays(gathered_arrays, names=gathered_names)

    def _gpu_gather_table_np(self, table: pa.Table, idx_np: np.ndarray, N: int) -> pa.Table:
        """Like _gpu_gather_table but accepts a numpy index array directly.

        Used in _execute_hash_join on the GPU path: the join kernels already return
        numpy int32 index arrays, so we skip the _np_of(idx_tensor) step of
        _gpu_gather_table.  For float32/int32 columns the gather runs on GPU via the
        'gather_f32' / 'gather_i32' Mojo kernels; string/date columns fall back to
        PyArrow .take() on CPU.
        """
        def _get_gather_model(mojo_name: str, arr_dtype: DType, source_len: int):
            # Cache key includes source_len: source table size determines graph input
            # type for position 0; different table sizes require different compiled models.
            ck = (mojo_name, source_len, N, self._session_device)
            m = _POST_OP_MODEL_CACHE.get(ck)
            if m is None:
                val_type = TensorType(arr_dtype, [source_len], self._device_ref)
                idx_type = TensorType(DType.int32, [N], self._device_ref)
                g = Graph(
                    name=f"mxframe_{mojo_name}",
                    input_types=[val_type, idx_type],
                    custom_extensions=[Path(self.kernels_path)],
                )
                with g:
                    out = ops.custom(
                        name=mojo_name,
                        values=[g.inputs[0], g.inputs[1]],
                        out_types=[TensorType(arr_dtype, [N], self._device_ref)],
                        device=self._device_ref,
                    )[0]
                    g.output(out)
                m = self._session.load(g)
                _POST_OP_MODEL_CACHE[ck] = m
            return m

        idx_int32 = idx_np.astype(np.int32)
        idx_buf = driver.Buffer.from_numpy(idx_int32).to(self._gpu_driver)

        gathered_arrays = []
        gathered_names = []
        for col_name in table.column_names:
            col = table.column(col_name)
            if isinstance(col, pa.ChunkedArray):
                col = _combine(col)
            source_len = len(col)
            if pa.types.is_float32(col.type):
                model = _get_gather_model("gather_f32", DType.float32, source_len)
                col_buf = driver.Buffer.from_numpy(
                    _np_of(col, zero_copy_only=False).astype(np.float32)
                ).to(self._gpu_driver)
                (out_t,) = model.execute(col_buf, idx_buf)
                gathered_arrays.append(_npa(np.asarray(_np_of(out_t)).reshape(-1)))
            elif pa.types.is_integer(col.type):
                model = _get_gather_model("gather_i32", DType.int32, source_len)
                col_buf = driver.Buffer.from_numpy(
                    _np_of(col, zero_copy_only=False).astype(np.int32)
                ).to(self._gpu_driver)
                (out_t,) = model.execute(col_buf, idx_buf)
                gathered_arrays.append(_npa(np.asarray(_np_of(out_t)).reshape(-1)))
            else:
                # Non-numeric column (string, date, etc.): CPU fallback
                gathered_arrays.append(pc.take(col, _npa(idx_int32.astype(np.int64))))
            gathered_names.append(col_name)

        return pa.Table.from_arrays(gathered_arrays, names=gathered_names)

    def _apply_distinct_custom(self, table, distinct_node):
        """Distinct rows of ``cols`` in first-appearance order (like pyarrow's group_by).

        Uses the engine's own group-key encoding: pyarrow's Table.group_by imports
        pyarrow.dataset and with it pandas (~150 ms of a first query).
        """
        cols = list(distinct_node.subset or table.column_names)
        sub = table.select(cols)
        if sub.num_rows == 0:
            return sub                                   # no rows: already distinct
        if any(sub.column(c).null_count for c in cols):
            return _distinct_rows(sub)
        from . import native_exec
        out = native_exec.try_distinct(self, sub)
        if out is not None:
            return out
        try:
            gids, n_groups, _ = self._build_group_ids(sub, cols)
        except Exception:
            return _distinct_rows(sub)
        rows = _group_keys.first_rows(gids, int(n_groups)) if isinstance(gids, np.ndarray) else None
        if rows is not None:
            return pc.take(sub, _npa(rows))
        gids = np.asarray(gids, dtype=np.int64)
        first = np.full(int(n_groups), len(gids), dtype=np.int64)
        np.minimum.at(first, gids, np.arange(len(gids), dtype=np.int64))
        return pc.take(sub, _npa(np.sort(first[first < len(gids)])))

    def _apply_post_ops_custom(self, table: pa.Table, post_ops: list) -> pa.Table:
        """Apply Sort/Limit/Distinct using Mojo kernels (not PyArrow compute)."""
        i = 0
        while i < len(post_ops):
            node = post_ops[i]
            if isinstance(node, Sort):
                # Peek ahead: if next op is a Limit, pass k to sort_topk (Phase 5)
                next_node = post_ops[i + 1] if i + 1 < len(post_ops) else None
                k = next_node.n if isinstance(next_node, Limit) else None
                table = self._apply_sort_custom(table, node, topk=k)
                i += 1
                # If we pre-applied the limit via topk, skip the Limit node
                if k is not None and isinstance(next_node, Limit):
                    i += 1   # consume the Limit — sort already returned k rows
            elif isinstance(node, Limit):
                table = table.slice(0, node.n)
                i += 1
            elif isinstance(node, Distinct):
                table = self._apply_distinct_custom(table, node)
                i += 1
            elif isinstance(node, Tail):
                table = table.slice(max(0, table.num_rows - node.n), node.n)
                i += 1
            else:
                i += 1
        return table


    # -- Join materialization ------------------------------------------

    @staticmethod
    def _plan_stable_key(plan) -> tuple | None:
        """Return a stable, hashable key for a Filter|Project→Scan chain.

        Used to cache join results across repeated .compute() calls on the same
        input tables with identical filter/projection predicates.  Returns None
        for plans that are too complex to cheaply fingerprint (nested joins, …).
        """
        if isinstance(plan, Scan):
            _watch_table(plan.table)
            return (id(plan.table), plan.table.num_rows)
        if isinstance(plan, Filter):
            inner = CustomOpsCompiler._plan_stable_key(plan.input)
            if inner is None:
                return None
            return inner + (plan.predicate.signature(),)
        if isinstance(plan, Project):
            inner = CustomOpsCompiler._plan_stable_key(plan.input)
            if inner is None:
                return None
            return inner + ("project", tuple(e.signature(True) for e in plan.exprs))
        return None

    def _materialize_joins(self, plan, needed=None):
        """Replace Join nodes by Scans of their results (F-018: see ``join_engine``).

        ``needed`` is the set of column names read from ``plan``'s output (None: all); each join
        only produces the columns read above it, and a chain of inner joins is reordered and
        gathered once.  Results are cached in _JOIN_RESULT_CACHE on hot calls over the same tables.
        """
        from . import join_engine
        return join_engine.materialize(self, plan, needed)

    @staticmethod
    def _scan_of(plan):
        node = plan.input if isinstance(plan, Project) else plan
        preds = []
        while isinstance(node, Filter):
            preds.append(node.predicate)
            node = node.input
        return (node, preds) if isinstance(node, Scan) else (None, preds)

    def _deferred_dicts(self, plan):
        """Dictionary columns resolve_plan left encoded for this single-table plan (F-046f)."""
        scan, _ = self._scan_of(plan)
        return frozenset(getattr(scan, "_mx_decode_after", None) or ()) if scan is not None else frozenset()

    def _decode_scan_dicts(self, plan, deferred):
        """The plan with its scan's deferred dictionary columns decoded (the pre-F-046f way)."""
        scan, _ = self._scan_of(plan)
        t = _decode_deferred_cols(scan.table, deferred)

        def swap(p):
            if p is scan:
                return Scan(t)
            if isinstance(p, Filter):
                return Filter(swap(p.input), p.predicate)
            if isinstance(p, Project):
                return Project(swap(p.input), p.exprs)
            return p

        return swap(plan)

    def _single_table(self, plan, post_ops, deferred):
        """One table, filtered, selected, maybe DISTINCT (F-046f / F-046g): the native filter decodes
        only the rows that pass, and keeps the codes of a DISTINCT's columns, which runs on the codes;
        only the distinct rows are decoded. (None, post_ops) when the plan is another shape."""
        if not deferred or _native_exec is None or self._session_device == "gpu":
            return None, post_ops
        scan, preds = self._scan_of(plan)
        if scan is None or not preds:
            return None, post_ops
        proj = plan if isinstance(plan, Project) else None
        names = [e.args[0] for e in proj.exprs] if proj is not None else list(scan.table.column_names)
        distinct = bool(post_ops) and isinstance(post_ops[0], Distinct) and not post_ops[0].subset
        keep = (deferred & set(names)) if distinct else frozenset()
        try:
            out = _native_exec.try_filter(self, scan.table, preds, set(names), keep_dict=keep)
        except Exception as exc:
            out = _native_exec.swallowed(exc, "leaf filter")
        if out is None:
            return None, post_ops
        out = pa.Table.from_arrays([out.column(n) for n in names],
                                   names=[e._alias or e.args[0] for e in proj.exprs] if proj is not None else names)
        if proj is None:
            out = out.replace_schema_metadata(scan.table.schema.metadata)
        if distinct:
            codes = pa.Table.from_arrays(
                [c.chunk(0).indices if pa.types.is_dictionary(c.type) else c for c in out.columns],
                names=out.column_names) if out.num_rows else out
            idx = _native_exec.try_distinct(self, codes, rows_only=True) if out.num_rows else None
            if idx is not None:
                out = out if isinstance(idx, pa.Table) else pc.take(out, _npa(idx))
                post_ops = post_ops[1:]
            out = _decode_deferred_cols(out, set(out.column_names))
        return out, post_ops

    def _filter_topk(self, plan, post_ops):
        """WHERE ... ORDER BY ... LIMIT k over one table in one native pass (F-046e): passing rows
        go straight into per-worker heaps, and only the k winners are gathered. The plan is
        Filter*(Scan), or a Project of plain columns over it; None for anything else."""
        if _native_exec is None or self._session_device == "gpu" or not post_ops or len(post_ops) < 2:
            return None
        srt, lim = post_ops[0], post_ops[1]
        if not (isinstance(srt, Sort) and isinstance(lim, Limit)) or lim.n is None or not (0 < lim.n <= 65536):
            return None
        proj, node = None, plan
        if isinstance(node, Project):
            proj, node = node, node.input
        preds = []
        while isinstance(node, Filter):
            preds.append(node.predicate)
            node = node.input
        if not isinstance(node, Scan) or not preds or node.table.num_rows < 8 * lim.n:
            return None
        table = node.table
        if proj is not None:
            if not all(isinstance(e, Expr) and e.op == "col" for e in proj.exprs):
                return None
            src = {(e._alias or e.args[0]): e.args[0] for e in proj.exprs}
        else:
            src = {n: n for n in table.column_names}
        by = []
        for e in srt.by:
            if not (isinstance(e, Expr) and e.op == "col" and e.args[0] in src):
                return None
            by.append(src[e.args[0]])
        desc = list(srt.descending) if isinstance(srt.descending, (list, tuple)) \
            else [bool(srt.descending)] * len(by)
        try:
            idx = _native_exec.try_filter_topk(self, table, preds, by, desc, lim.n)
        except Exception as exc:
            return _native_exec.swallowed(exc, "filter + top-k")
        if idx is None:
            return None
        keep = table if proj is None else table.select(list(dict.fromkeys(src.values())))
        rows = _decode_deferred_cols(pc.take(keep, _npa(idx)), self._deferred_dicts(plan))  # by source name
        if proj is None:
            return rows
        return pa.Table.from_arrays([rows.column(e.args[0]) for e in proj.exprs],
                                    names=[e._alias or e.args[0] for e in proj.exprs])

    def _native_filter_scan(self, plan, needed):
        """Filter*(Scan) in one native pass (F-044: a WHERE without an aggregate, e.g. before ORDER BY
        ... LIMIT), keeping ``needed`` columns (None: all). None when the plan is another shape or a
        column it returns is a dictionary (the native filter decodes them; the result keeps types)."""
        if _native_exec is None:
            return None
        preds, node = [], plan
        while isinstance(node, Filter):
            preds.append(node.predicate)
            node = node.input
        if not isinstance(node, Scan) or not preds:
            return None
        return self._native_filter_table(node.table, preds, needed)

    def _native_filter_table(self, t, preds, needed):
        """The rows of table ``t`` passing every predicate in one native pass (a column the result keeps
        must not be a dictionary), or None."""
        cols = [f for f in t.schema if needed is None or f.name in needed]
        if not cols or any(pa.types.is_dictionary(f.type) for f in cols):
            return None
        try:
            out = _native_exec.try_filter(self, t, preds, None if needed is None else set(needed))
        except Exception as exc:
            return _native_exec.swallowed(exc, "leaf filter")
        return None if out is None else out.replace_schema_metadata(t.schema.metadata)

    def _plan_to_table(self, plan) -> pa.Table:
        """Resolve a plan subtree (no Aggregate) to a concrete pa.Table via PyArrow.

        Handles:
        - Scan: return table directly
        - Filter → ... → Scan: apply predicates eagerly in PyArrow
        - Project: evaluate all exprs via _eval_expr_arrow (handles strings, year, etc.)
        - Anything complex: delegate to compile_and_run
        """
        if isinstance(plan, Scan):
            return plan.table
        if isinstance(plan, (Filter, Project)) and self._contains_aggregate(plan.input):
            # F-033: a subquery's HAVING (a Filter over an Aggregate, with or without a select above it) is
            # the executor's HAVING, not a predicate evaluated in Arrow over every group
            return self.compile_and_run(plan)
        if isinstance(plan, Filter):
            got = self._native_filter_scan(plan, None)
            if got is not None:
                return got
            preds, node = [], plan
            while isinstance(node, Filter):
                preds.append(node.predicate)
                node = node.input
            inner_table = self._plan_to_table(node)
            if not isinstance(node, Scan) and _native_exec is not None:
                got = self._native_filter_table(inner_table, preds, None)
                if got is not None:                     # F-034: the filters over a computed table (TPC-H Q22's
                    return got                            # select + isin + balance test) in one native pass
            for p in _raising_last(reversed(preds)):
                inner_table = pc.filter(inner_table, self._eval_predicate(p, inner_table))
            return inner_table
        if isinstance(plan, Project):
            inner_table = None
            if isinstance(plan.input, Filter):
                need = set()
                for expr in plan.exprs:
                    _expr_col_names(expr, need)
                inner_table = self._native_filter_scan(plan.input, need)
            if inner_table is None:
                inner_table = self._plan_to_table(plan.input)
            got = _np_float_project(plan.exprs, inner_table)
            if got is not None:
                return got
            arrays, names = [], []
            for expr in plan.exprs:
                arr = self._eval_expr_arrow(expr, inner_table)
                name = expr._alias or (expr.args[0] if expr.op == "col" else f"col_{len(arrays)}")
                arrays.append(arr)
                names.append(name)
            return pa.Table.from_arrays(arrays, names=names)
        # For anything more complex (Aggregate etc.), use the full compiler
        return self.compile_and_run(plan)

    def _execute_hash_join(self, left_table, right_table, left_on, right_on, how="inner"):
        """Execute a hash join: inner via Mojo, left outer via PyArrow.

        how="inner": Mojo GPU/CPU kernels, all matching rows.
        how="left":  PyArrow left outer; unmatched left rows get null right cols.
        """
        if how in ("semi", "anti"):
            # left rows with (semi) / without (anti) a partner, left columns only, in left order
            from .join_engine import has_partner
            if left_table.num_rows and right_table.num_rows:
                left_keys, right_keys = self._encode_join_key_pair(left_table, right_table, left_on, right_on)
                hit = has_partner(np.asarray(left_keys), np.asarray(right_keys))
            else:
                hit = np.zeros(left_table.num_rows, dtype=bool)
            keep = ~hit if how == "anti" else hit
            return pc.take(left_table, _npa(np.flatnonzero(keep).astype(np.int64)))
        if how == "left":
            # Mojo left-outer join: join_count_left + join_scatter_left kernels.
            left_keys, right_keys = self._encode_join_key_pair(
                left_table, right_table, left_on, right_on
            )
            if self._session_device == "gpu" and self._aot is None:
                left_idx, right_idx = self._hash_join_left_mojo_gpu(left_keys, right_keys)
            else:
                left_idx, right_idx = self._hash_join_left_mojo_cpu(left_keys, right_keys)
            return self._assemble_left_outer(left_table, right_table, right_on,
                                             left_idx, right_idx)

        # inner join via Mojo kernels
        left_keys, right_keys = self._encode_join_key_pair(
            left_table, right_table, left_on, right_on
        )

        # Route by session device (GPU join kernels for GPU sessions, CPU kernels otherwise): `inner_pairs`
        from .join_engine import inner_pairs
        left_idx, right_idx = inner_pairs(self, left_keys, right_keys)

        n_result = len(left_idx)

        # Assemble joined table.
        # Phase 4: AOT GPU gather (single index H2D, cached source columns).
        # Fallback: GPU MAX Graph gather for large results, PyArrow for small.
        if self._session_device == "gpu" and self._aot_gpu is not None and n_result > 0:
            def gather(t, ix):
                return gpu_budget.run_piece(
                    "gather", gpu_budget.gather_bytes(t, len(ix)), lambda: self._aot_gpu.gather_table(t, ix),
                    lambda: _take_rows(t, ix), shape=(t.num_rows, len(ix), str(t.schema.types)))
            left_take, right_take = gather(left_table, left_idx), gather(right_table, right_idx)
        else:
            left_take = _take_rows(left_table, left_idx)
            right_take = _take_rows(right_table, right_idx)

        # Combine: all left columns + right columns excluding join keys
        arrays = []
        names = []
        for col_name in left_table.column_names:
            arrays.append(left_take.column(col_name))
            names.append(col_name)
        for col_name, out_name in join_output_names(left_table.column_names, right_table.column_names, right_on):
            arrays.append(right_take.column(col_name))
            names.append(out_name)

        return pa.Table.from_arrays(arrays, names=names)

    @staticmethod
    def _common_key_type(a, b):
        """The type both join key types convert to without changing any value, else None
        (int32 with int64 -> int64; float32 with float64 -> float64; an integer with a float is
        paired by join_engine.int_float_pair when exact; numbers with
        strings never match silently)."""
        if pa.types.is_dictionary(a):
            a = a.value_type
        if pa.types.is_dictionary(b):
            b = b.value_type
        if a == b:
            return a
        if pa.types.is_integer(a) and pa.types.is_integer(b):
            if pa.types.is_unsigned_integer(a) != pa.types.is_unsigned_integer(b):
                # a signed type that holds every value of both: uint32 with int64 -> int64, uint32 with
                # int32 -> int64; uint64 with any signed integer has none and is refused
                u, sg = (a, b) if pa.types.is_unsigned_integer(a) else (b, a)
                if u.bit_width >= 64:
                    return None
                return sg if sg.bit_width > u.bit_width else {8: pa.int16(), 16: pa.int32(), 32: pa.int64()}[u.bit_width]
            return a if a.bit_width >= b.bit_width else b
        if pa.types.is_floating(a) and pa.types.is_floating(b):
            return a if a.bit_width >= b.bit_width else b
        if pa.types.is_string(a) and pa.types.is_large_string(b) or pa.types.is_large_string(a) and pa.types.is_string(b):
            return pa.large_string()
        return None

    @staticmethod
    def _encode_join_key_pair(left_table, right_table, left_cols, right_cols):
        """Encode both join sides into one shared dense int32 key space.

        Encoding each table independently is incorrect for strings because Arrow
        assigns dictionary IDs in encounter order. A single dictionary over both
        sides guarantees that equal values receive equal IDs. Multi-column keys
        are then jointly densified, avoiding mixed-radix overflow and keeping the
        AOT hash table compact. Nulls receive side-specific IDs and never match.
        """
        if len(left_cols) != len(right_cols) or not left_cols:
            raise ValueError("join key column lists must be non-empty and equal length")

        from .join_engine import int_float_pair
        n_left = len(left_table)
        paired_codes = []
        for left_name, right_name in zip(left_cols, right_cols):
            left_arr = _combine(left_table.column(left_name))
            right_arr = _combine(right_table.column(right_name))
            if left_arr.type != right_arr.type:
                common = CustomOpsCompiler._common_key_type(left_arr.type, right_arr.type)
                if common is not None:
                    left_arr, right_arr = pc.cast(left_arr, common), pc.cast(right_arr, common)
                elif (pair := int_float_pair(left_arr, right_arr)) is not None:
                    left_arr, right_arr = pair
                else:
                    raise TypeError(
                        f"join key types differ: {left_name}={left_arr.type}, "
                        f"{right_name}={right_arr.type}"
                    )
            left_arr, right_arr = _canonical_floats(left_arr), _canonical_floats(right_arr)   # F-079

            if (
                len(left_cols) == 1
                and pa.types.is_integer(left_arr.type)
                and left_arr.null_count == 0
                and right_arr.null_count == 0
            ):
                left_np = _np_of(left_arr, zero_copy_only=False)
                right_np = _np_of(right_arr, zero_copy_only=False)
                all_keys = np.concatenate([left_np, right_np])
                if len(all_keys) == 0:
                    return (
                        np.empty(n_left, dtype=np.int32),
                        np.empty(len(right_table), dtype=np.int32),
                    )
                max_key = int(all_keys.max())
                if int(all_keys.min()) >= 0 and max_key <= max(1024, 4 * len(all_keys)):
                    return (
                        np.ascontiguousarray(left_np.astype(np.int32)),
                        np.ascontiguousarray(right_np.astype(np.int32)),
                    )

            encoded = pc.dictionary_encode(pa.concat_arrays([left_arr, right_arr]))
            codes = _np_of(pc.fill_null(encoded.indices, _npscalar(-1, type=encoded.indices.type)), zero_copy_only=False).astype(np.int64)
            nulls = codes < 0
            if nulls.any():
                next_code = len(encoded.dictionary)
                codes[:n_left][nulls[:n_left]] = next_code
                codes[n_left:][nulls[n_left:]] = next_code + 1
            paired_codes.append(codes)

        if len(paired_codes) == 1:
            dense = paired_codes[0]
        else:
            matrix = np.column_stack(paired_codes)
            _, dense = np.unique(matrix, axis=0, return_inverse=True)

        dense = dense.astype(np.int32, copy=False)
        return (
            np.ascontiguousarray(dense[:n_left]),
            np.ascontiguousarray(dense[n_left:]),
        )

    def _assemble_left_outer(self, left_table, right_table, right_on, left_idx, right_idx):
        """Assemble left-outer result. right_idx==-1 means no match (null right cols)."""
        left_take = _take_rows(left_table, left_idx)
        has_match = (right_idx >= 0)
        safe_right = right_idx.copy()
        safe_right[~has_match] = 0
        null_mask_arr = _npa(~has_match)
        arrays, names = [], []
        for col_name in left_table.column_names:
            arrays.append(left_take.column(col_name))
            names.append(col_name)
        empty_right = right_table.num_rows == 0
        right_take = None if empty_right else _take_rows(right_table, safe_right)
        for col_name, out_name in join_output_names(left_table.column_names, right_table.column_names, right_on):
            if empty_right:                       # nothing to take from: every row is unmatched
                arrays.append(pa.nulls(len(left_idx), type=right_table.schema.field(col_name).type))
                names.append(out_name)
                continue
            col_arr = right_take.column(col_name)
            if not has_match.all():
                col_arr = pc.if_else(pc.invert(null_mask_arr), col_arr, None)
            arrays.append(col_arr)
            names.append(out_name)
        return pa.Table.from_arrays(arrays, names=names)

    def _hash_join_left_mojo_cpu(self, left_keys, right_keys):
        """CPU left-outer hash join via AOT ctypes kernels (no MAX Graph)."""
        n_left  = len(left_keys)
        n_right = len(right_keys)
        if n_left == 0:
            return np.array([], dtype=np.int32), np.array([], dtype=np.int32)
        lk = np.ascontiguousarray(left_keys.astype(np.int32))
        rk = np.ascontiguousarray(right_keys.astype(np.int32)) if n_right > 0 else np.array([], dtype=np.int32)

        if self._aot is not None:
            mc = self._aot.join_count_left(lk, rk)
            lo, ro = self._aot.join_scatter_left(lk, rk, mc)
            return lo, ro
        # Pass 1: count
        ck1 = ("join_count_left_cpu", n_left, n_right, self._session_device)
        m1 = _POST_OP_MODEL_CACHE.get(ck1)
        if m1 is None:
            g = Graph(
                name="mxframe_jcl_cpu",
                input_types=[TensorType(DType.int32, [n_left], self._device_ref),
                              TensorType(DType.int32, [max(n_right,1)], self._device_ref)],
                custom_extensions=[Path(self.kernels_path)],
            )
            with g:
                mc = ops.custom("join_count_left_cpu",
                                values=[g.inputs[0], g.inputs[1]],
                                out_types=[TensorType(DType.int32, [n_left], self._device_ref)],
                                device=self._device_ref)[0]
                g.output(mc)
            m1 = self._session.load(g)
            _POST_OP_MODEL_CACHE[ck1] = m1
        rk_in = rk if n_right > 0 else np.zeros(1, dtype=np.int32)
        (mc_t,) = m1.execute(lk, rk_in)
        mc = np.asarray(_np_of(mc_t)).reshape(-1).astype(np.int32)
        total = int(mc.sum(dtype=np.int64))
        check_join_output_size(total)
        offsets = np.zeros(n_left, dtype=np.int32)
        if n_left > 1:
            np.cumsum(mc[:-1], out=offsets[1:])
        # Pass 2: scatter
        ck2 = ("join_scatter_left_cpu", n_left, n_right, total, self._session_device)
        m2 = _POST_OP_MODEL_CACHE.get(ck2)
        if m2 is None:
            g = Graph(
                name="mxframe_jsl_cpu",
                input_types=[TensorType(DType.int32, [n_left], self._device_ref),
                              TensorType(DType.int32, [max(n_right,1)], self._device_ref),
                              TensorType(DType.int32, [n_left], self._device_ref)],
                custom_extensions=[Path(self.kernels_path)],
            )
            with g:
                lo, ro = ops.custom("join_scatter_left_cpu",
                                    values=[g.inputs[0], g.inputs[1], g.inputs[2]],
                                    out_types=[TensorType(DType.int32, [total], self._device_ref),
                                               TensorType(DType.int32, [total], self._device_ref)],
                                    device=self._device_ref)
                g.output(lo, ro)
            m2 = self._session.load(g)
            _POST_OP_MODEL_CACHE[ck2] = m2
        lo_t, ro_t = m2.execute(lk, rk_in, offsets)
        left_idx  = np.asarray(_np_of(lo_t)).reshape(-1).astype(np.int32)
        right_idx = np.asarray(_np_of(ro_t)).reshape(-1).astype(np.int32)
        return left_idx, right_idx

    def _hash_join_left_mojo_gpu(self, left_keys, right_keys):
        """GPU left-outer join. Falls back to CPU Mojo on error."""
        try:
            return self._hash_join_left_mojo_gpu_impl(left_keys, right_keys)
        except Exception:
            return self._hash_join_left_mojo_cpu(left_keys, right_keys)

    def _hash_join_left_mojo_gpu_impl(self, left_keys, right_keys):
        n_left  = len(left_keys)
        n_right = len(right_keys)
        if n_left == 0:
            return np.array([], dtype=np.int32), np.array([], dtype=np.int32)
        lk = left_keys.astype(np.int32)
        rk = right_keys.astype(np.int32) if n_right > 0 else np.array([], dtype=np.int32)
        all_keys = np.concatenate([lk, rk]) if n_right > 0 else lk
        max_key = int(all_keys.max())
        table_size = max_key + 1
        max_key_arr = np.array([max_key], dtype=np.int32)
        rk_in = rk if n_right > 0 else np.zeros(1, dtype=np.int32)
        n_right_in = max(n_right, 1)
        # Pass 1
        ck1 = ("join_count_left_gpu", n_left, n_right, table_size, self._session_device)
        m1 = _POST_OP_MODEL_CACHE.get(ck1)
        if m1 is None:
            g = Graph(
                name="mxframe_jcl_gpu",
                input_types=[TensorType(DType.int32, [n_left], self._device_ref),
                              TensorType(DType.int32, [n_right_in], self._device_ref),
                              TensorType(DType.int32, [1], self._device_ref)],
                custom_extensions=[Path(self.kernels_path)],
            )
            with g:
                mc, _ = ops.custom("join_count_left_gpu",
                                   values=[g.inputs[0], g.inputs[1], g.inputs[2]],
                                   out_types=[TensorType(DType.int32, [n_left], self._device_ref),
                                              TensorType(DType.int32, [table_size], self._device_ref)],
                                   device=self._device_ref)
                g.output(mc)
            m1 = self._session.load(g)
            _POST_OP_MODEL_CACHE[ck1] = m1
        (mc_t,) = m1.execute(lk, rk_in, max_key_arr)
        mc = np.asarray(_np_of(mc_t)).reshape(-1).astype(np.int32)
        total = int(mc.sum(dtype=np.int64))
        check_join_output_size(total)
        offsets = np.zeros(n_left, dtype=np.int32)
        if n_left > 1:
            np.cumsum(mc[:-1], out=offsets[1:])
        # Build sorted right arrays
        right_count = np.zeros(table_size, dtype=np.int32)
        if n_right > 0:
            np.add.at(right_count, rk.clip(0, table_size - 1), 1)
        right_key_starts = np.zeros(table_size, dtype=np.int32)
        np.cumsum(right_count[:-1], out=right_key_starts[1:])
        cursor = right_key_starts.copy()
        right_sorted_idx = np.zeros(max(n_right, 1), dtype=np.int32)
        for i, k_v in enumerate(rk):
            k_i = int(k_v)
            right_sorted_idx[cursor[k_i]] = i
            cursor[k_i] += 1
        # Pass 2
        ck2 = ("join_scatter_left_gpu", n_left, n_right, total, table_size, self._session_device)
        m2 = _POST_OP_MODEL_CACHE.get(ck2)
        if m2 is None:
            g = Graph(
                name="mxframe_jsl_gpu",
                input_types=[
                    TensorType(DType.int32, [n_left],      self._device_ref),
                    TensorType(DType.int32, [n_right_in],  self._device_ref),
                    TensorType(DType.int32, [n_left],      self._device_ref),
                    TensorType(DType.int32, [n_right_in],  self._device_ref),
                    TensorType(DType.int32, [table_size],  self._device_ref),
                    TensorType(DType.int32, [table_size],  self._device_ref),
                ],
                custom_extensions=[Path(self.kernels_path)],
            )
            with g:
                lo, ro = ops.custom("join_scatter_left_gpu",
                                    values=[g.inputs[i] for i in range(6)],
                                    out_types=[TensorType(DType.int32, [total], self._device_ref),
                                               TensorType(DType.int32, [total], self._device_ref)],
                                    device=self._device_ref)
                g.output(lo, ro)
            m2 = self._session.load(g)
            _POST_OP_MODEL_CACHE[ck2] = m2
        lo_t, ro_t = m2.execute(lk, rk_in, offsets, right_sorted_idx, right_key_starts, right_count)
        left_idx  = np.asarray(_np_of(lo_t)).reshape(-1).astype(np.int32)
        right_idx = np.asarray(_np_of(ro_t)).reshape(-1).astype(np.int32)
        return left_idx, right_idx

    @staticmethod
    def _hash_join_numpy(left_keys: np.ndarray, right_keys: np.ndarray):
        """Session-free fully vectorized inner hash join using NumPy sort + searchsorted.

        Used on GPU sessions with small/medium inputs where Mojo GPU join kernels would
        incur more PCIe round-trip overhead than the join itself costs on CPU.
        All operations are vectorized (no Python loops) - O(n log n) time.
        """
        # Sort right side once
        right_order = np.argsort(right_keys, kind='stable').astype(np.int32)
        sorted_right = right_keys[right_order]

        # For each left key find the matching range [lo, hi) in sorted right
        lo = np.searchsorted(sorted_right, left_keys, side='left')
        hi = np.searchsorted(sorted_right, left_keys, side='right')
        counts = (hi - lo).astype(np.int64)

        n_out = int(counts.sum())
        if n_out == 0:
            return np.empty(0, dtype=np.int32), np.empty(0, dtype=np.int32)

        # Build left_out: each left key repeated counts[i] times
        left_out = np.repeat(
            np.arange(len(left_keys), dtype=np.int32), counts
        )

        # Build right_out: fully vectorized using cumsum offsets
        # For output row k belonging to left_key j:
        #   right index = right_order[lo[j] + relative_position_within_j]
        start_offsets = np.empty(len(left_keys), dtype=np.int64)
        start_offsets[0] = 0
        if len(left_keys) > 1:
            np.cumsum(counts[:-1], out=start_offsets[1:])
        relative_pos = (
            np.arange(n_out, dtype=np.int64)
            - np.repeat(start_offsets, counts)
        )
        right_indexer = lo[left_out].astype(np.int64) + relative_pos
        right_out = right_order[right_indexer].astype(np.int32)

        return left_out, right_out

    def _hash_join_mojo_cpu(self, left_keys, right_keys):
        """CPU path: two-pass hash join via AOT ctypes kernels (no MAX Graph).

        Falls back to MAX Graph join_count_cpu/join_scatter_cpu on older builds
        where AOT is not available.
        """
        n_left = len(left_keys)
        n_right = len(right_keys)
        if n_left == 0 or n_right == 0:
            return np.array([], dtype=np.int32), np.array([], dtype=np.int32)

        lk = np.ascontiguousarray(left_keys.astype(np.int32, copy=False))
        rk = np.ascontiguousarray(right_keys.astype(np.int32, copy=False))

        if self._aot is not None:
            mc = self._aot.join_count(lk, rk)
            total = int(mc.sum(dtype=np.int64))
            check_join_output_size(total)
            if total == 0:
                return np.array([], dtype=np.int32), np.array([], dtype=np.int32)
            lo, ro = self._aot.join_scatter(lk, rk, mc)
            return lo, ro

        # ── AOT not available: fall back to MAX Graph join_count_cpu / join_scatter_cpu ──
        left_keys_i32 = lk
        right_keys_i32 = rk
        cache_key_count = ("join_count_cpu", n_left, n_right, self._session_device)
        model_count = _POST_OP_MODEL_CACHE.get(cache_key_count)
        if model_count is None:
            lk_type = TensorType(DType.int32, [n_left], self._device_ref)
            rk_type = TensorType(DType.int32, [n_right], self._device_ref)
            graph = Graph(
                name="mxframe_join_count_cpu",
                input_types=[lk_type, rk_type],
                custom_extensions=[Path(self.kernels_path)],
            )
            with graph:
                match_counts_node = ops.custom(
                    name="join_count_cpu",
                    values=[graph.inputs[0], graph.inputs[1]],
                    out_types=[
                        TensorType(DType.int32, [n_left], self._device_ref),
                    ],
                    device=self._device_ref,
                )[0]
                graph.output(match_counts_node)
            model_count = self._session.load(graph)
            _POST_OP_MODEL_CACHE[cache_key_count] = model_count

        (match_counts_out,) = model_count.execute(left_keys_i32, right_keys_i32)
        match_counts = np.asarray(_np_of(match_counts_out)).reshape(-1).astype(np.int32)

        # -- Python bridge: total + offsets --
        total = int(match_counts.sum())
        if total == 0:
            return np.array([], dtype=np.int32), np.array([], dtype=np.int32)

        offsets = np.zeros(n_left, dtype=np.int32)
        np.cumsum(match_counts[:-1], out=offsets[1:])

        # -- Pass 2: Scatter via Mojo CPU kernel --
        cache_key_scatter = ("join_scatter_cpu", n_left, n_right, total, self._session_device)
        model_scatter = _POST_OP_MODEL_CACHE.get(cache_key_scatter)
        if model_scatter is None:
            lk_type = TensorType(DType.int32, [n_left], self._device_ref)
            rk_type = TensorType(DType.int32, [n_right], self._device_ref)
            off_type = TensorType(DType.int32, [n_left], self._device_ref)
            graph = Graph(
                name="mxframe_join_scatter_cpu",
                input_types=[lk_type, rk_type, off_type],
                custom_extensions=[Path(self.kernels_path)],
            )
            with graph:
                left_out_node, right_out_node = ops.custom(
                    name="join_scatter_cpu",
                    values=[graph.inputs[0], graph.inputs[1], graph.inputs[2]],
                    out_types=[
                        TensorType(DType.int32, [total], self._device_ref),
                        TensorType(DType.int32, [total], self._device_ref),
                    ],
                    device=self._device_ref,
                )
                graph.output(left_out_node, right_out_node)
            model_scatter = self._session.load(graph)
            _POST_OP_MODEL_CACHE[cache_key_scatter] = model_scatter

        left_out_t, right_out_t = model_scatter.execute(left_keys_i32, right_keys_i32, offsets)
        left_idx = np.asarray(_np_of(left_out_t)).reshape(-1).astype(np.int32)
        right_idx = np.asarray(_np_of(right_out_t)).reshape(-1).astype(np.int32)

        return left_idx, right_idx

    def _hash_join_mojo_gpu(self, left_keys, right_keys):
        """GPU path: two-pass hash join via Mojo kernels through MAX Graph.

        Pass 1 (join_count): count matches per left row.
        Python bridge: sum → total, prefix sum → offsets.
        Pass 2 (join_scatter): emit index pairs using pre-built position arrays.
        """
        n_left = len(left_keys)
        n_right = len(right_keys)
        max_key = max(int(left_keys.max()), int(right_keys.max())) if n_left > 0 and n_right > 0 else 0
        table_size = max_key + 1

        left_keys_i32 = left_keys.astype(np.int32)
        right_keys_i32 = right_keys.astype(np.int32)

        # -- Pass 1: Count matches via GPU kernel --
        max_key_buf = np.array([max_key], dtype=np.int32)

        cache_key_count = ("join_count_gpu", n_left, n_right, table_size, self._session_device)
        model_count = _POST_OP_MODEL_CACHE.get(cache_key_count)
        if model_count is None:
            lk_type = TensorType(DType.int32, [n_left], self._device_ref)
            rk_type = TensorType(DType.int32, [n_right], self._device_ref)
            mk_type = TensorType(DType.int32, [1], self._device_ref)
            graph = Graph(
                name="mxframe_join_count",
                input_types=[lk_type, rk_type, mk_type],
                custom_extensions=[Path(self.kernels_path)],
            )
            with graph:
                match_counts_node, right_count_node = ops.custom(
                    name="join_count_gpu",
                    values=[graph.inputs[0], graph.inputs[1], graph.inputs[2]],
                    out_types=[
                        TensorType(DType.int32, [n_left], self._device_ref),
                        TensorType(DType.int32, [table_size], self._device_ref),
                    ],
                    device=self._device_ref,
                )
                graph.output(match_counts_node, right_count_node)
            model_count = self._session.load(graph)
            _POST_OP_MODEL_CACHE[cache_key_count] = model_count

        lk_buf = driver.Buffer.from_numpy(left_keys_i32).to(self._gpu_driver)
        rk_buf = driver.Buffer.from_numpy(right_keys_i32).to(self._gpu_driver)
        mk_buf = driver.Buffer.from_numpy(max_key_buf).to(self._gpu_driver)
        match_counts_out, _ = model_count.execute(lk_buf, rk_buf, mk_buf)
        match_counts = np.asarray(_np_of(match_counts_out)).reshape(-1).astype(np.int32)

        # -- Python bridge --
        total = int(match_counts.sum())
        if total == 0:
            return np.array([], dtype=np.int32), np.array([], dtype=np.int32)

        offsets = np.zeros(n_left, dtype=np.int32)
        np.cumsum(match_counts[:-1], out=offsets[1:])

        # -- Build right-side position arrays for GPU scatter --
        right_count = np.bincount(right_keys_i32, minlength=table_size).astype(np.int32)
        right_order = np.argsort(right_keys_i32, kind='stable').astype(np.int32)
        right_starts = np.zeros(table_size, dtype=np.int32)
        np.cumsum(right_count[:-1], out=right_starts[1:])

        # -- Pass 2: Scatter via GPU kernel --
        cache_key_scatter = ("join_scatter_gpu", n_left, n_right, total, table_size, self._session_device)
        model_scatter = _POST_OP_MODEL_CACHE.get(cache_key_scatter)
        if model_scatter is None:
            lk_type = TensorType(DType.int32, [n_left], self._device_ref)
            rk_type = TensorType(DType.int32, [n_right], self._device_ref)
            off_type = TensorType(DType.int32, [n_left], self._device_ref)
            rsi_type = TensorType(DType.int32, [n_right], self._device_ref)
            rks_type = TensorType(DType.int32, [table_size], self._device_ref)
            rkc_type = TensorType(DType.int32, [table_size], self._device_ref)
            graph = Graph(
                name="mxframe_join_scatter",
                input_types=[lk_type, rk_type, off_type, rsi_type, rks_type, rkc_type],
                custom_extensions=[Path(self.kernels_path)],
            )
            with graph:
                left_out_node, right_out_node = ops.custom(
                    name="join_scatter_gpu",
                    values=[graph.inputs[0], graph.inputs[1], graph.inputs[2],
                            graph.inputs[3], graph.inputs[4], graph.inputs[5]],
                    out_types=[
                        TensorType(DType.int32, [total], self._device_ref),
                        TensorType(DType.int32, [total], self._device_ref),
                    ],
                    device=self._device_ref,
                )
                graph.output(left_out_node, right_out_node)
            model_scatter = self._session.load(graph)
            _POST_OP_MODEL_CACHE[cache_key_scatter] = model_scatter

        off_buf = driver.Buffer.from_numpy(offsets).to(self._gpu_driver)
        rsi_buf = driver.Buffer.from_numpy(right_order).to(self._gpu_driver)
        rks_buf = driver.Buffer.from_numpy(right_starts).to(self._gpu_driver)
        rkc_buf = driver.Buffer.from_numpy(right_count).to(self._gpu_driver)
        left_out_t, right_out_t = model_scatter.execute(lk_buf, rk_buf, off_buf, rsi_buf, rks_buf, rkc_buf)
        left_idx = np.asarray(_np_of(left_out_t)).reshape(-1).astype(np.int32)
        right_idx = np.asarray(_np_of(right_out_t)).reshape(-1).astype(np.int32)

        return left_idx, right_idx

    @staticmethod
    def _build_group_ids(table, keys):
        """Dictionary-encode group keys into contiguous int32 group ids."""
        if len(keys) == 1:
            encoded = _encode_key(table.column(keys[0]))
            ids = _np_of(encoded.indices, zero_copy_only=False).astype(np.int32, copy=False)
            return ids, len(encoded.dictionary), {keys[0]: encoded.dictionary}

        encodings = []
        for k in keys:
            encodings.append(_encode_key(table.column(k)))

        sizes = [len(e.dictionary) for e in encodings]
        strides = []
        for i in range(len(sizes)):
            s = 1
            for j in range(i + 1, len(sizes)):
                s *= sizes[j]
            strides.append(s)
        max_groups = strides[0] * sizes[0]

        if max_groups >= (1 << 62):
            # the mixed-radix composite would overflow int64: fold the keys in one at a time, replacing
            # the running key by its dense rank whenever the next radix would overflow it
            codes = [_np_of(e.indices, zero_copy_only=False).astype(np.int64) for e in encodings]
            running, span = codes[0], sizes[0]
            for c, size in zip(codes[1:], sizes[1:]):
                if span * size >= (1 << 62):
                    uniq, running = np.unique(running, return_inverse=True)
                    running, span = running.astype(np.int64), len(uniq)
                running, span = running * size + c, span * size
            uniq, first, dense_ids = np.unique(running, return_index=True, return_inverse=True)
            unique_key_cols = {k: pc.take(encodings[i].dictionary, _npa(codes[i][first]))
                               for i, k in enumerate(keys)}
            return dense_ids.astype(np.int32), len(uniq), unique_key_cols

        # int64: with int32 the composite of a few high-cardinality keys (an order key and a supplier
        # key) wrapped around and merged distinct groups (Distinct dropped 3080 of 6M rows at SF1)
        index_arrays = [_np_of(enc.indices, zero_copy_only=False) for enc in encodings]
        composite = _group_keys.composite(index_arrays, strides)
        if composite is None:
            composite = np.zeros(len(table), dtype=np.int64)
            for i, idx in enumerate(index_arrays):
                composite += idx.astype(np.int64) * np.int64(strides[i])

        if max_groups <= 1024:
            present_mask = np.zeros(max_groups, dtype=bool)
            present_mask[composite] = True
            present = np.where(present_mask)[0]
            n_groups = len(present)

            if n_groups == max_groups:
                dense_ids = composite.astype(np.int32)
            else:
                remap = np.empty(max_groups, dtype=np.int32)
                remap[present] = np.arange(n_groups, dtype=np.int32)
                dense_ids = remap[composite]

            unique_key_cols = {}
            for i, k in enumerate(keys):
                key_idx = (present // strides[i]) % sizes[i]
                unique_key_cols[k] = pc.take(encodings[i].dictionary,
                    _npa(key_idx.astype(np.int64))
                )
            return dense_ids, n_groups, unique_key_cols

        ranked = _group_keys.dense_sorted(composite, lead=(strides[0], sizes[0]))
        if ranked is not None:
            dense_ids, unique_composite, _ = ranked
        else:
            unique_composite, dense_ids = np.unique(composite, return_inverse=True)
            dense_ids = dense_ids.astype(np.int32)
        n_groups = len(unique_composite)

        unique_key_cols = {}
        for i, k in enumerate(keys):
            key_idx = ((unique_composite // strides[i]) % sizes[i]).astype(np.int64)
            unique_key_cols[k] = pc.take(encodings[i].dictionary, _npa(key_idx))

        return dense_ids, n_groups, unique_key_cols

    def _build_group_ids_multikey_mojo(self, table, keys):
        """Multi-key group ID encoding using the Mojo group_composite kernel.

        Phase 16: replaces the NumPy per-key loop
            composite += _np_of(enc.indices) * stride
        with a single fused Mojo kernel pass over all key columns simultaneously.
        This improves cache efficiency (one memory pass vs K passes) for
        multi-column groupby (Q7, Q8, Q9, Q10).

        Returns (dense_ids, n_groups, unique_key_cols) or None on failure.
        """
        if len(keys) > 4:
            return None        # the kernel takes four key slots: a fifth key would be left out of the composite
        try:
            # Dictionary-encode each key column (PyArrow SIMD — not replicated in Mojo)
            encodings = []
            for k in keys:
                encodings.append(_encode_key(table.column(k)))

            sizes = [len(e.dictionary) for e in encodings]
            strides_list = []
            for i in range(len(sizes)):
                s = 1
                for j in range(i + 1, len(sizes)):
                    s *= sizes[j]
                strides_list.append(s)
            max_groups = strides_list[0] * sizes[0]
            n_rows = len(table)

            # Extract int32 index arrays from dictionary encoding
            key_arrs = [
                _np_of(e.indices, zero_copy_only=False).astype(np.int32)
                for e in encodings
            ]
            # Pad to exactly 4 key slots with zero arrays
            while len(key_arrs) < 4:
                key_arrs.append(np.zeros(n_rows, dtype=np.int32))
            strides_padded = list(strides_list) + [0] * (4 - len(strides_list))
            strides_i64 = np.array(strides_padded[:4], dtype=np.int64)

            # Mojo kernel: fused composite key computation (single memory pass)
            composite = self._run_group_composite_kernel(
                key_arrs[0], key_arrs[1], key_arrs[2], key_arrs[3], strides_i64
            )  # int64 array of length n_rows

            # Fast path: dense cartesian product (max_groups small enough for bitmask)
            if max_groups <= max(1024, min(1 << 22, 2 * n_rows)):      # a direct table beats sorting the rows
                present_mask = np.zeros(max_groups, dtype=bool)
                present_mask[composite] = True
                present = np.where(present_mask)[0]
                n_groups = len(present)
                if n_groups == max_groups:
                    dense_ids = composite.astype(np.int32)
                else:
                    remap = np.empty(max_groups, dtype=np.int32)
                    remap[present] = np.arange(n_groups, dtype=np.int32)
                    dense_ids = remap[composite.astype(np.int32)]
                unique_key_cols = {}
                for i, k in enumerate(keys):
                    key_idx = (present // strides_list[i]) % sizes[i]
                    unique_key_cols[k] = pc.take(encodings[i].dictionary,
                        _npa(key_idx.astype(np.int64))
                    )
                return dense_ids, n_groups, unique_key_cols

            # Sparse path: numpy sort-based densification
            unique_composite, dense_inv = np.unique(composite, return_inverse=True)
            dense_ids = dense_inv.astype(np.int32)
            n_groups = len(unique_composite)
            unique_key_cols = {}
            for i, k in enumerate(keys):
                key_idx = ((unique_composite // strides_list[i]) % sizes[i]).astype(np.int64)
                unique_key_cols[k] = pc.take(encodings[i].dictionary, _npa(key_idx))
            return dense_ids, n_groups, unique_key_cols
        except Exception:
            return None

    def _run_group_composite_kernel(self, k0, k1, k2, k3, strides_i64):
        """Execute group_composite Mojo kernel on CPU path.

        Inputs: k0..k3 are int32 numpy arrays of length n_rows.
                strides_i64 is an int64 numpy array of length 4.
        Returns: int64 numpy array of length n_rows.
        """
        # Elementwise op on host arrays: the CPU AOT kernel is right on either device
        # (no GPU round trip, no MAX Graph JIT).
        if self._aot is not None:
            return self._aot.group_composite(k0, k1, k2, k3, strides_i64)
        n_rows = len(k0)
        cache_key = ("group_composite", n_rows, self._session_device)
        model = _POST_OP_MODEL_CACHE.get(cache_key)
        if model is None:
            k_type = TensorType(DType.int32, [n_rows], self._device_ref)
            s_type = TensorType(DType.int64, [4], self._device_ref)
            out_type = TensorType(DType.int64, [n_rows], self._device_ref)
            graph = Graph(
                name="mxframe_group_composite",
                input_types=[k_type, k_type, k_type, k_type, s_type],
                custom_extensions=[Path(self.kernels_path)],
            )
            with graph:
                out_node = ops.custom(
                    name="group_composite",
                    values=[
                        graph.inputs[0], graph.inputs[1],
                        graph.inputs[2], graph.inputs[3],
                        graph.inputs[4],
                    ],
                    out_types=[out_type],
                    device=self._device_ref,
                )[0]
                graph.output(out_node)
            model = self._session.load(graph)
            _POST_OP_MODEL_CACHE[cache_key] = model
        (out,) = model.execute(k0, k1, k2, k3, strides_i64)
        return np.asarray(_np_of(out)).reshape(-1)

    @staticmethod
    def _build_group_ids_cached(table, keys, gpu_compiler=None):
        """Cached wrapper: reuses group encoding when the same table object is queried.

        Dispatch priority:
          1. GPU session + single integer key  → _build_group_ids_gpu_single_int
             (Phase 3: AOT GPU hash-table encode, no PyArrow dictionary_encode)
          2. Multi-key with gpu_compiler       → _build_group_ids_multikey_mojo
             (fused composite-key computation via Mojo group_composite kernel)
          3. CPU fallback                      → _build_group_ids (PyArrow)
        """
        _watch_table(table)
        cache_key = (id(table), table.num_rows, tuple(keys))
        cached = _GROUP_ENCODE_CACHE.get(cache_key)
        if cached is not None:
            return cached

        # Dictionary-encoded keys (F-015): ids straight from the Arrow code buffers.
        from . import group_keys as _group_keys
        result = _group_keys.build(table, keys)
        if result is not None:
            _GROUP_ENCODE_CACHE[cache_key] = result
            return result

        # GPU single integer-key path: skip PyArrow dictionary_encode entirely
        if (gpu_compiler is not None
                and gpu_compiler._session_device == "gpu"
                and len(keys) == 1):
            col_arr = table.column(keys[0])
            if isinstance(col_arr, pa.ChunkedArray):
                col_arr = _combine(col_arr)
            if pa.types.is_integer(col_arr.type):
                result = gpu_compiler._build_group_ids_gpu_single_int(
                    col_arr, keys[0], len(table)
                )
                if result is not None:
                    _GROUP_ENCODE_CACHE[cache_key] = result
                    return result

        # Mojo path for multi-key groupby: fused composite key computation
        if gpu_compiler is not None and len(keys) > 1:
            result = gpu_compiler._build_group_ids_multikey_mojo(table, keys)
            if result is not None:
                _GROUP_ENCODE_CACHE[cache_key] = result
                return result

        result = CustomOpsCompiler._build_group_ids(table, keys)
        _GROUP_ENCODE_CACHE[cache_key] = result
        return result

    def _build_group_ids_gpu_single_int(self, col_arr, key_name, n_rows):
        """GPU group encoding for a single integer key column.

        Phase 3: uses the AOT group_encode_i32_gpu ctypes kernel when available
        (no MAX Graph JIT cold start, no large H2D table uploads).  Falls back
        to the MAX Graph group_encode kernel, then to CPU path.

        Returns (dense_ids, n_groups, unique_key_cols) or None on failure.
        """
        if self._aot_gpu is None:       # no GPU AOT library: the caller encodes on the CPU (no MAX Graph JIT)
            return None
        try:
            keys_np = _np_of(col_arr, zero_copy_only=False).astype(np.int32)
            n = len(keys_np)
            if n == 0:
                return np.array([], dtype=np.int32), 0, {key_name: _npa([], type=pa.int32())}

            # Capacity: next power of two >= 2*n (load factor <= 0.5)
            cap = 1
            while cap < 2 * n:
                cap *= 2

            # ── AOT fast path (no JIT, no large table H2D uploads) ─────────────
            if self._aot_gpu is not None:
                dense_ids, n_groups = gpu_budget.run_piece(   # out of GPU memory: the caller encodes on the CPU
                    "group encode", 4 * n + 8 * cap + 4 * n, lambda: self._aot_gpu.group_encode_i32(keys_np, cap),
                    gpu_budget.leave_gpu, shape=(n, cap))
            else:
                # ── MAX Graph fallback ────────────────────────────────────────
                capacity_np = np.array([cap], dtype=np.int32)
                key_table_np = np.full(cap, -2147483648, dtype=np.int32)
                id_table_np  = np.full(cap, -1, dtype=np.int32)

                cache_key = ("group_encode", n, cap, self._session_device)
                model = _POST_OP_MODEL_CACHE.get(cache_key)
                if model is None:
                    k_type  = TensorType(DType.int32, [n],   self._device_ref)
                    cap_type = TensorType(DType.int32, [1],  self._device_ref)
                    kt_type = TensorType(DType.int32, [cap], self._device_ref)
                    graph = Graph(
                        name="mxframe_group_encode",
                        input_types=[k_type, cap_type, kt_type, kt_type],
                        custom_extensions=[Path(self.kernels_path)],
                    )
                    with graph:
                        gids_node, ng_node, _, _ = ops.custom(
                            name="group_encode",
                            values=[graph.inputs[0], graph.inputs[1],
                                    graph.inputs[2], graph.inputs[3]],
                            out_types=[
                                TensorType(DType.int32, [n],   self._device_ref),
                                TensorType(DType.int32, [1],   self._device_ref),
                                TensorType(DType.int32, [cap], self._device_ref),
                                TensorType(DType.int32, [cap], self._device_ref),
                            ],
                            device=self._device_ref,
                        )
                        graph.output(gids_node, ng_node)
                    model = self._session.load(graph)
                    _POST_OP_MODEL_CACHE[cache_key] = model

                k_buf  = driver.Buffer.from_numpy(keys_np).to(self._gpu_driver)
                c_buf  = driver.Buffer.from_numpy(capacity_np).to(self._gpu_driver)
                kt_buf = driver.Buffer.from_numpy(key_table_np).to(self._gpu_driver)
                it_buf = driver.Buffer.from_numpy(id_table_np).to(self._gpu_driver)
                group_ids_t, n_groups_t = model.execute(k_buf, c_buf, kt_buf, it_buf)
                dense_ids = np.asarray(_np_of(group_ids_t)).reshape(-1).astype(np.int32)
                n_groups  = int(np.asarray(_np_of(n_groups_t)).reshape(-1)[0])

            # ── Reconstruct unique key values (vectorized, O(N log N)) ────────
            # For each dense ID 0..n_groups-1 find the first original position.
            # Stable argsort ensures ties preserve encounter order.
            sort_order = np.argsort(dense_ids, kind='stable')   # position → sorted pos
            sorted_gids = dense_ids[sort_order]
            first_in_sorted = np.searchsorted(
                sorted_gids, np.arange(n_groups, dtype=np.int32), side='left'
            )
            first_occurrence = sort_order[first_in_sorted].astype(np.int64)
            unique_keys = pc.take(col_arr, _npa(first_occurrence))
            return dense_ids, n_groups, {key_name: unique_keys}

        except MemoryError:
            if gpu_budget.strict():
                raise
            return None  # fall back to CPU path
        except Exception:
            return None  # fall back to CPU path


